    public static String getCirclesContactlessLBDoorMsg(int FLAG, int FLAG2) {
        String x = "";
        Context ctx = myApp.getAppContext();
        try {
            String start = ctx.getString(R.string.ifintend);
            String fullm = "";
            String end = "";
            if ((FLAG & 1) == 1) {
                fullm += "\n- " + ctx.getString(R.string.lblSI_1_1_1_1);
            }
            if ((FLAG & 2) == 2) {
                fullm += "\n- " + ctx.getString(R.string.lblSI_1_2_2_2);
            }
            if ((FLAG & 4) == 4) {
                fullm += "\n- " + ctx.getString(R.string.lblSI_1_3_3_3);
            }
            if ((FLAG2 & 2048) == 2048) {
                fullm += "\n- " + ctx.getString(R.string.lblSI_1_6_6_6);
            }
            end = ctx.getString(R.string.calltoverifyaddress);
            x = start + fullm + end;
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception at JobsHandler getCirclesContactlessLBDoorMsg. Exception: " + e.getMessage(), "", "", "", "");
        } finally {
            return x;
        }
    }

