    public static void startRulingTimer(Date lastModDate, final Long subDuration) {
        long lastModDateT = 0;
        long currTimeMS = new Date().getTime();
        try {
            if (rulingTimer == null) {
                if (lastModDate != null) {
                    lastModDateT = lastModDate.getTime();
                    if (subDuration == null) {
                        objGlobalMethods.logPR_latemsg0("1st image taken.", false);
                    }
                    long leftTimeMS = (subDuration != null ? subDuration : 420000) - (currTimeMS - lastModDateT);
                    //long leftTimeMS = (subDuration != null ? subDuration : 120000) - (currTimeMS - lastModDateT);
                    rulingTimer = new CountDownTimer(leftTimeMS, 1000) {

                        public void onTick(long millisUntilFinished) {
                            //do nothing
                        }

                        public void onFinish() {
                            objGlobalMethods.showPR_lateprompt();
                        }
                    }.start();
                    objGlobalMethods.writeToFile("Start rulingTimer.", "", "", "", "");
                }
            }
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exeption at JobsHandler startRulingTimer. Exception: " + e.getMessage(), "", "", "", "");
        }
    }

    public static void disposeRulingTimer() {
        try {
            if (rulingTimer != null) {
                objGlobalMethods.writeToFile("rulingTimer not null. Setting rulingTimer.cancel() and to null.", "", "", "", "");
                rulingTimer.cancel();
                rulingTimer = null;
            } else {
                //objGlobalMethods.writeToFile("rulingTimer is null.", "", "", "", "");
            }
            rulingTimer = null;
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception at JobsHandler disposeRulingTimer. Exception: " + e.getMessage(), "", "", "", "");
        }
    }

    private static Date toDateTime(Date date) {
        Calendar c = Calendar.getInstance();
        c.setTime(date);
        return new Date(
                c.get(Calendar.YEAR),
                c.get(Calendar.MONTH),
                c.get(Calendar.DAY_OF_MONTH),
                c.get(Calendar.HOUR_OF_DAY),
                c.get(Calendar.MINUTE));
    }

