    public static String getRecipientNameFromJob(objJobInfo ji) {
        String name = "";
        objAddressStructure DELAddressStructure = null;
        objContactStructure DELcontactStructure = null;
        try {
            if (ji.DLRedirectedLocation != null) {
                DELAddressStructure = ji.DLRedirectedLocation;
            } else if (ji.DLLocation != null) {
                DELAddressStructure = ji.DLLocation;
            } else {
                DELAddressStructure = null;
            }

            if (DELAddressStructure != null && DELAddressStructure.Contacts != null) {
                DELcontactStructure = DELAddressStructure.Contacts[0];
                if (DELcontactStructure.NAME != null && !DELcontactStructure.NAME.equals("")) {
                    name = DELcontactStructure.NAME;
                }
            }
        } catch (Exception e) {
            String stack = getStackTraceString(e);
            objGlobalMethods.writeToFile("Exception at JobsHandler getRecipientNameFromJob. Exception: " + e.getMessage().toLowerCase(), "", "", "", "");
            name = "";
        } finally {
            return name;
        }
    }

