    public static void AddRemoveClearObjCallback(SharedPreferences gcmp, String JobNo, String ContactNos, boolean Clear) {
        if (gcmp == null) {
            gcmp = objGlobalMethods.getGcmPreferences();
        }
        String objCallCheckJsonStr = objGlobalMethods.getGCMPrefs(gcmp, "objCallCheckJsonStr");
        objCallCheck occ = null;
        ArrayList<String> ContactNoList = null;
        try {
            if (Clear && !objGlobalMethods.IsEmptyString(objCallCheckJsonStr)) {
                objGlobalMethods.setGCMPrefs(gcmp, "objCallCheckJsonStr", "");
            } else if ((!objGlobalMethods.IsEmptyString(ContactNos))) {
                Gson gson = new Gson();
                if (!objGlobalMethods.IsEmptyString(objCallCheckJsonStr)) {
                    occ = gson.fromJson(objCallCheckJsonStr, objCallCheck.class);
                    if (occ != null && occ.ContactNo != null) {
                        boolean AnyContactNoExists = occ.ContactNosExists(ContactNos);
                        if (!AnyContactNoExists) {
                            occ.clearJobNos();
                            occ.clearContactNo();
                        }
                        occ.addJobNos(JobNo);
                        occ.addContactNo(ContactNos);
                        objCallCheckJsonStr = gson.toJson(occ);
                        objGlobalMethods.setGCMPrefs(gcmp, "objCallCheckJsonStr", objCallCheckJsonStr);
                    }
                } else {
                    occ = new objCallCheck();
                    occ.addJobNos(JobNo);
                    occ.addContactNo(ContactNos);
                    objCallCheckJsonStr = gson.toJson(occ);
                    objGlobalMethods.setGCMPrefs(gcmp, "objCallCheckJsonStr", objCallCheckJsonStr);
                }
            }


        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception at JobsHandler AddRemoveClearObjCallback. Exception: " + e.getMessage(), "", "", "", "");
        }
    }

    //start Hash SHA1
    private static String convertToHex(byte[] data) {
        StringBuilder buf = new StringBuilder();
        for (byte b : data) {
            int halfbyte = (b >>> 4) & 0x0F;
            int two_halfs = 0;
            do {
                buf.append((0 <= halfbyte) && (halfbyte <= 9) ? (char) ('0' + halfbyte) : (char) ('a' + (halfbyte - 10)));
                halfbyte = b & 0x0F;
            } while (two_halfs++ < 1);
        }
        return buf.toString().toUpperCase();
    }

    public static String SHA1(String text) throws NoSuchAlgorithmException, UnsupportedEncodingException {
        MessageDigest md = MessageDigest.getInstance("SHA-1");
        md.update(text.getBytes("iso-8859-1"), 0, text.length());
        byte[] sha1hash = md.digest();
        return convertToHex(sha1hash);
    }

