    public static void updateSentMessagetoDelivered(SharedPreferences gcmMsgPrefs, long msgID, Boolean currAct) {
        try {
            mutex.acquire();
            String ChatMsgSendersALJsonStr;
            Gson gson = new Gson();
            long selectedMsgID;
            ArrayList<ChatMessage> chatMessages = new ArrayList<>();
            ChatMsgSenders[] ChatMsgSendersAL;
            ChatMsgSenders chatmsgsenders = null;
            ChatMsgSendersALJsonStr = objGlobalMethods.getGCMPrefs(gcmMsgPrefs, "ChatMsgSendersALJsonStr");
            mutex.release();
            if (!ChatMsgSendersALJsonStr.equals("")) {
                ChatMsgSendersAL = gson.fromJson(ChatMsgSendersALJsonStr, ChatMsgSenders[].class);
                if (ChatMsgSendersAL != null) {
                    outerloop:
                    for (int i = 0; i <= ChatMsgSendersAL.length - 1; i++) {
                        chatmsgsenders = ChatMsgSendersAL[i];
                        chatMessages = chatmsgsenders.chatMessages;
                        for (int x = 0; x <= chatMessages.size() - 1; x++) {
                            selectedMsgID = chatMessages.get(x).getID();
                            if (selectedMsgID == msgID) {
                                chatMessages.get(x).setMessageStatus(Status.DELIVERED);
                                break outerloop;
                            }
                        }
                    }

                    updateChatMsgSenders(gcmMsgPrefs, chatmsgsenders);

                    if (currAct) {
                        Messaging.chatMessages = chatMessages;
                    }
                }
            }


        } catch (Exception e) {
            Date dt = new Date();
            objGlobalMethods.writeToFile("Exception at JobsHandler updateSentMessagetoDelivered. Exception: " + e.getMessage().toString(), "", "", "", "");
            mutex.release();
        } finally {
            mutex.release();
        }
    }

    public static ArrayList<ChatMessage> processUpdateDateToChatMessage(ArrayList<ChatMessage> achatMessages) {
        Date dt = new Date();
        ArrayList<ChatMessage> aachatMessages = achatMessages;
        ArrayList<ChatMessage> aachatMessages2 = new ArrayList<>();
        DateFormat dateFormat = new SimpleDateFormat("dd/MM/yyyy");
        try {
            for (int i = 0; i <= aachatMessages.size() - 1; i++) {
                if (aachatMessages.get(i).messageDate == null) {
                    Calendar cal = Calendar.getInstance();
                    cal.add(Calendar.DATE, -1);
                    //aachatMessages.get(i).messageDate = cal.getTime();
                    aachatMessages.get(i).messageDate = cal.getTimeInMillis();
                    aachatMessages.get(i).setMessageText(dateFormat.format(cal.getTime()));
                }

                if (aachatMessages.get(i).getUserType() == UserType.DATE && !dateFormat.format(aachatMessages.get(i).messageDate).equals(dateFormat.format(dt))) {
                    aachatMessages.get(i).setMessageText(dateFormat.format(aachatMessages.get(i).messageDate));
                }
                aachatMessages2.add(aachatMessages.get(i));
            }
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception caught at JobsHandler processUpdateDateToChatMessage. " + e.getMessage().toString(), "", "", "", "");
            aachatMessages2 = achatMessages;
        } finally {
            return aachatMessages2;
        }
    }

