    public static void updateSystemJobConsignmentNote(Context context, SharedPreferences GcmPreferences, long JobsIDX, objJobInfo currJobInfo, int categoryType, String AConsignmentNote) {
        try {
            objJobInfo[] consignmentJobInfoAL;
            objJobInfo[] consignmentsubJobInfoAL;
            Gson gson = new Gson();
            String JsonStr = "";
            mutexgcm.acquire();
            if (categoryType == 0) {
                JsonStr = GcmPreferences.getString(objGlobalVariables.JobInfoPIPALjsonPrefName, "");
            } else if (categoryType == 1) {
                JsonStr = GcmPreferences.getString(objGlobalVariables.JobInfoPUALjsonPrefName, "");
            } else if (categoryType == 2) {
                JsonStr = GcmPreferences.getString(objGlobalVariables.JobInfoDIPALjsonPrefName, "");
            } else if (categoryType == 3) {
                JsonStr = GcmPreferences.getString(objGlobalVariables.JobInfoDELALjsonPrefName, "");
            } else if (categoryType == 4) {
                JsonStr = GcmPreferences.getString(objGlobalVariables.JobInfoFPALjsonPrefName, "");
            } else if (categoryType == 5) {
                JsonStr = GcmPreferences.getString(objGlobalVariables.JobInfoFDALjsonPrefName, "");
            }
            consignmentsubJobInfoAL = gson.fromJson(GcmPreferences.getString("hfJobsInfoArrJsonStr", ""), objJobInfo[].class);
            mutexgcm.release();

            consignmentJobInfoAL = gson.fromJson((String) JsonStr, objJobInfo[].class);
            objJobInfo ji;
            for (int i = 0; i <= consignmentJobInfoAL.length - 1; i++) {
                ji = (objJobInfo) consignmentJobInfoAL[i];
                if (JobsIDX == ji.JobsIDX) {
                    consignmentJobInfoAL[i] = currJobInfo;
                    break;
                }
            }

            if (consignmentsubJobInfoAL != null) {
                List<objJobInfo> JobInfoList;
                JobInfoList = new ArrayList<objJobInfo>(Arrays.asList(consignmentsubJobInfoAL));
                for (int i = 0; i <= JobInfoList.size() - 1; i++) {
                    ji = JobInfoList.get(i);
                    if (JobsIDX == ji.JobsIDX) {
                        ji.setConsignmentNote(AConsignmentNote);
                        break;
                    }
                }
                consignmentsubJobInfoAL = JobInfoList.toArray(new objJobInfo[JobInfoList.size()]);
                String Jsonstr = gson.toJson(consignmentsubJobInfoAL);
                sethfJobsInfoArrJsonStrPref(GcmPreferences, Jsonstr);
            }

            String JobInfoJsonStr = "";
            JobInfoJsonStr = gson.toJson(consignmentJobInfoAL);
            if (categoryType == 0) {
                setCategoryHashes(context, GcmPreferences, objGlobalVariables.JobInfoPIPALjsonPrefName, JobInfoJsonStr);
            } else if (categoryType == 1) {
                setCategoryHashes(context, GcmPreferences, objGlobalVariables.JobInfoPUALjsonPrefName, JobInfoJsonStr);
            } else if (categoryType == 2) {
                setCategoryHashes(context, GcmPreferences, objGlobalVariables.JobInfoDIPALjsonPrefName, JobInfoJsonStr);
            } else if (categoryType == 3) {
                setCategoryHashes(context, GcmPreferences, objGlobalVariables.JobInfoDELALjsonPrefName, JobInfoJsonStr);
            } else if (categoryType == 4) {
                setCategoryHashes(context, GcmPreferences, objGlobalVariables.JobInfoFPALjsonPrefName, JobInfoJsonStr);
            } else if (categoryType == 5) {
                setCategoryHashes(context, GcmPreferences, objGlobalVariables.JobInfoFDALjsonPrefName, JobInfoJsonStr);
            }

        } catch (Exception e) {
            Date dt = new Date();
            objGlobalMethods.writeToFile("Exception at JobsHandler updateSystemJobConsignmentNote. Exception: " + e.getMessage().toString(), "", "", "", "");
        } finally {

        }
    }

