    public static void setSystemCategoryJobsIDXhashSQLite(SharedPreferences GcmPreferences, int categoryType) {
        Long[] affectedJobsIDXlongArr = null;
        String cHashstr = "";
        try {
            //JobsIDX related
            affectedJobsIDXlongArr = DAO_Jobs.getAllJobsIDXPerCategory(categoryType);
            if (affectedJobsIDXlongArr != null && affectedJobsIDXlongArr.length > 0) {
                //get new hash
                Arrays.sort(affectedJobsIDXlongArr);
                String s = "";
                for (int v = 0; v <= affectedJobsIDXlongArr.length - 1; v++) {
                    s += "[" + String.valueOf(affectedJobsIDXlongArr[v]) + "]";
                }

                if (!s.trim().equals("")) {
                    try {
                        cHashstr = SHA1(s);
                    } catch (Exception e) {
                        s = "";
                        cHashstr = "";
                    }
                } else {
                    cHashstr = "";
                }
            } else {
                cHashstr = "";
            }

            if (categoryType == 0) {
                //pip
                setCategoryHashes(GcmPreferences, objGlobalVariables.PIPhashName, cHashstr);
            } else if (categoryType == 1) {
                //pu
                setCategoryHashes(GcmPreferences, objGlobalVariables.PUhashName, cHashstr);
            } else if (categoryType == 2) {
                //dip
                setCategoryHashes(GcmPreferences, objGlobalVariables.DIPhashName, cHashstr);
            } else if (categoryType == 3) {
                //del
                setCategoryHashes(GcmPreferences, objGlobalVariables.DELhashName, cHashstr);
            } else if (categoryType == 4) {
                //fp
                setCategoryHashes(GcmPreferences, objGlobalVariables.FPhashName, cHashstr);
            } else if (categoryType == 5) {
                //fd
                setCategoryHashes(GcmPreferences, objGlobalVariables.FDhashName, cHashstr);
            }
        } catch (Exception e) {
            String stack = getStackTraceString(e);
            objGlobalMethods.writeToFile("Exception at JobsHandler setSystemCategoryJobsIDXhashSQLite. Exception: " + e.getMessage().toString() + "\n" + "Stack: " + stack, "", "", "", "");
        }
    }

