    public static Boolean ProcessDOincForSubmission(SharedPreferences gcmp, SharedPreferences usp, String ARegID, Long JobsIDX) {
        Boolean fullyProcessed = true;
        //List<objJobIDxDOinvIDx> JobIDxDOinvIDxList = null;
        //objJobIDxDOinvIDx JobIDxDOinvIDx = null;
        List<objJobDOtags> JobDOtagsList = null;
        objJobDOtags JobDOtags = null;
        String JobIDxDOinvIDxListStr = "";
        Gson gson = new Gson();
        Date dt = new Date();
        Long l = dt.getTime();
        String timestampstr = "/Date(" + l + ")/";

        try {
            JobIDxDOinvIDxListStr = objGlobalMethods.getGCMPrefs(gcmp, "DOinvCheckList");

            if (!JobIDxDOinvIDxListStr.equals("") && !JobIDxDOinvIDxListStr.equals("[]")) {
                JobDOtagsList = gson.fromJson(JobIDxDOinvIDxListStr, new TypeToken<List<objJobDOtags>>() {
                }.getType());
            }

            if (JobDOtagsList != null && JobDOtagsList.size() > 0) {
                for (int i = 0; i <= JobDOtagsList.size() - 1; i++) {
                    JobDOtags = JobDOtagsList.get(i);
                    if (JobDOtags.JobsIDX.equals(JobsIDX)) {
                        if (JobDOtags.totalcount == JobDOtags.selectedcount) {
                            fullyProcessed = true;
                        } else if (JobDOtags.totalcount > JobDOtags.selectedcount) {
                            fullyProcessed = false;
                        }

                        if (JobDOtags.tags.size() > 0) {
                            String[] tagsArr = JobDOtags.tags.toArray(new String[JobDOtags.tags.size()]);
                            addUpdateDOQueALPrefs(usp, ARegID, JobDOtags.JobsIDX, tagsArr, true, timestampstr);
                            JobDOtagsList.remove(i);
                            if (JobDOtagsList.size() == 0) {
                                JobIDxDOinvIDxListStr = "";
                            } else {
                                JobIDxDOinvIDxListStr = gson.toJson(JobDOtagsList);
                            }
                            objGlobalMethods.setGCMPrefs(gcmp, "DOinvCheckList", JobIDxDOinvIDxListStr);
                        } else if (JobDOtags.tags.size() == 0) {
                            JobDOtagsList.remove(i);
                            if (JobDOtagsList.size() == 0) {
                                JobIDxDOinvIDxListStr = "";
                            } else {
                                JobIDxDOinvIDxListStr = gson.toJson(JobDOtagsList);
                            }
                            objGlobalMethods.setGCMPrefs(gcmp, "DOinvCheckList", JobIDxDOinvIDxListStr);
                        }

                        break;
                    }
                }
            } else {
                fullyProcessed = true;
            }

        } catch (Exception e) {
            fullyProcessed = false;
        } finally {
            return fullyProcessed;
        }
    }

