    public static void processDOinvCheckedItemsBeforeSubmit(Long JobsIDX, String tag, int totalcount, boolean Add, SharedPreferences gcmp) {
        String JobIDxDOinvIDxListStr = "";
        List<objJobDOtags> JobDOtagsList = null;
        objJobDOtags JobDOtags = null;

        Gson gson = new Gson();
        List<String> tags = null;

        try {
            JobIDxDOinvIDxListStr = objGlobalMethods.getGCMPrefs(gcmp, "DOinvCheckList");
            if (!JobIDxDOinvIDxListStr.equals("") && !JobIDxDOinvIDxListStr.equals("[]")) {
                JobDOtagsList = gson.fromJson(JobIDxDOinvIDxListStr, new TypeToken<List<objJobDOtags>>() {
                }.getType());
            }

            if (Add) {
                if (JobDOtagsList == null) {
                    JobDOtagsList = new ArrayList<>();
                    tags = new ArrayList<String>();
                    tags.add(tag);
                    //JobIDxDOinvIDx = new objJobIDxDOinvIDx(JobsIDX, InvoiceIDXs, totalcount, 1);
                    JobDOtags = new objJobDOtags(JobsIDX, tags, totalcount, 1);
                    JobDOtagsList.add(JobDOtags);
                } else {
                    for (int x = 0; x <= JobDOtagsList.size() - 1; x++) {
                        JobDOtags = JobDOtagsList.get(x);
                        if (JobDOtags.JobsIDX.equals(JobsIDX)) {
                            tags = JobDOtags.tags;
                            tags.add(tag);
                            JobDOtags.settags(tags);
                            JobDOtags.setSelectedcount(tags.size());
                            JobDOtagsList.set(x, JobDOtags);
                            break;
                        }
                    }
                }
            } else {
                if (JobDOtagsList != null && JobDOtagsList.size() > 0) {
                    outer:
                    for (int i = 0; i <= JobDOtagsList.size() - 1; i++) {
                        JobDOtags = JobDOtagsList.get(i);
                        if (JobDOtags.JobsIDX.equals(JobsIDX)) {
                            tags = JobDOtags.tags;
                            for (int x = 0; x <= tags.size() - 1; x++) {
                                if (tags.get(x).equals(tag)) {
                                    tags.remove(x);
                                    break;
                                }
                            }

                            JobDOtags.settags(tags);
                            JobDOtags.setSelectedcount(tags.size());
                            JobDOtagsList.set(i, JobDOtags);

                            break outer;
                        }
                    }

                } else {
                    JobDOtagsList = null;
                }
            }

            if (JobDOtagsList != null && JobDOtagsList.size() > 0) {
                JobIDxDOinvIDxListStr = gson.toJson(JobDOtagsList);
                objGlobalMethods.setGCMPrefs(gcmp, "DOinvCheckList", JobIDxDOinvIDxListStr);
            } else {
                objGlobalMethods.setGCMPrefs(gcmp, "DOinvCheckList", "");
            }

        } catch (Exception e) {
            Date dt = new Date();
            objGlobalMethods.writeToFile("Exception at JobsHandler processDOinvCheckedItemsBeforeSubmit. Exception: " + e.getMessage().toString(), "", "", "", "");
        }
    }

