    //=======================================================================================================================================================================

    public static void startBackendRun15SecCounter() {
        try {
            backEndIsRunning = false;
            FCMservice.enablePush = true;
            Context ctx = myApp.getAppContext();
            Intent i = new Intent(ctx, ActiveService.class);
            i.putExtra("durationSec", "15000");
            i.setAction(ActiveService.ACTION_START_COUNTDOWN_TIMER);
            ctx.startService(i);
        } catch (Exception e) {
            String s = e.getMessage();
            objGlobalMethods.writeToFile("Exception at JobsHandler startBackendRun15SecCounter. Exception: " + s, "", "", "", "");
        }
    }

    public static void backendRun(SharedPreferences GcmPreferences, SharedPreferences updateJobInfoPref) {
        //backend processes lineup
        //1. processUpdateJobInfoStatusQue2
        //2. processUpdateDunningStatusQue2
        //3. processUpdateJobConsignmentNoteQue2
        //4. processUpdateJobInfoPhotoQue2
        //5. processUpdateJobSignatureQue2
        //6. processUpdateTaggingQue2
        //7. processRemoveTaggingQue2
        //8. processUpdateCODQue2
        //9. processUpdateDOCODQue2
        //10. processUploadJobsheetQue2
        //11. processUploadBulkPickUpQue2
        //12. processUploadCreditCardQue2
        //13. processUploadCreditCard3HQue2
        //14. processUpdateRtnGPSQue2
        //15. processAckMessages2
        //16. processSendMessage2
        //17. processUpdateDO2
        //18. ResyncWholeListOrNot
        //19. End of Resync
        //R6: return before the connectivity check, so a blocked process neither processes queues nor re-arms the 15s retry counter
        if (RootGuard.blockOperation("JobsHandler.backendRun", null)) {
            return;
        }
        try {
            //cd = new ConnectionDetector(myApp.getAppContext());
            cd = new ConnectionDetector(null);
            if (cd.isConnectingToInternet()) {

                String[] UsernamePwd = new String[4];
                String username, useridx;
                UsernamePwd = objGlobalMethods.getLoginUsernamePwd(GcmPreferences);
                username = UsernamePwd[0];
                useridx = UsernamePwd[2];

                if (!backEndIsRunning) {
                    if (!objGlobalMethods.isStill_relogging_in()) {
                        backEndIsRunning = true;
                        FCMservice.enablePush = false;
                        processUpdateJobInfoStatusQue2(GcmPreferences, updateJobInfoPref);
                    } else {
                        objGlobalMethods.writeToFile("Backend not started due RegID changed n still attempting ot relogin.", "", "", username, useridx);
                    }
                } else {
                    //log down that backend if running
                    NewPerMinService.count += 1;
                    objGlobalMethods.writeToFile("Backend is running already.",
                            "", "", username, useridx);
                }
            } else {
                startBackendRun15SecCounter();
                objGlobalMethods.writeToFile("backendRun not started no matter what status due no Internet connection. Wait for Regain Internet connection to kick start backendRun.",
                        "", "", "", "");
            }
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception at JobsHandler backendRun. Exception: " + e.getMessage().toString(), "", "", "", "");
        }
    }

