    private static MessageQue getSendMessage2(SharedPreferences updateJobInfoPref) {
        Gson gson = new Gson();
        MessageQue[] msgQs;
        MessageQue msgQ = null;
        try {
            mutex.acquire();
            String sendMessagesArrPrefStr = updateJobInfoPref.getString("sendMessagesArrPrefStr", "");
            if (!sendMessagesArrPrefStr.isEmpty()) {
                msgQs = gson.fromJson(sendMessagesArrPrefStr, MessageQue[].class);
                if (msgQs != null) {
                    List<MessageQue> ListUpdateJobInfoStatusALAL = new ArrayList<MessageQue>(Arrays.asList(msgQs));
                    if (ListUpdateJobInfoStatusALAL.size() > 0) {
                        for (int i = 0; i <= ListUpdateJobInfoStatusALAL.size() - 1; i++) {
                            msgQ = ListUpdateJobInfoStatusALAL.get(i);
                            ListUpdateJobInfoStatusALAL.remove(i);
                            break;
                        }
                        msgQs = ListUpdateJobInfoStatusALAL.toArray(new MessageQue[ListUpdateJobInfoStatusALAL.size()]);
                        sendMessagesArrPrefStr = gson.toJson(msgQs);
                        SharedPreferences.Editor editor = updateJobInfoPref.edit();
                        if (sendMessagesArrPrefStr.equals("[]")) {
                            sendMessagesArrPrefStr = "";
                        }
                        editor.putString("sendMessagesArrPrefStr", sendMessagesArrPrefStr);
                        editor.apply();
                    }
                }
            }
        } catch (Exception e) {
            mutex.release();
            objGlobalMethods.writeToFile("Exception at JobsHandler getSendMessage. Exception: " + e.getMessage().toString(), "", "", "", "");
            msgQ = null;
        } finally {
            mutex.release();
            return msgQ;
        }
    }

