    public static void SendQuedEmails(SharedPreferences updateJobInfoPref, objEmailItem obj) {
        boolean succ = false;
        File myFile = null;
        try {
            if (obj.attachmentfilename != null && !obj.attachmentfilename.isEmpty() && !obj.attachmentfilename.equals("") && obj.attachmentfilename != "") {
                try {
                    myFile = new File(obj.attachmentfilename);
                    if (!myFile.isAbsolute()) {
                        myFile = null;
                        objGlobalMethods.writeToFile("SendQuedEmails !myFile.isAbsolute for " + obj.subjectstr, "", "", "", "");
                    } else {
                        objGlobalMethods.writeToFile("SendQuedEmails myFile.isAbsolute for " + obj.subjectstr, "", "", "", "");
                    }
                } catch (Exception e) {
                    objGlobalMethods.writeToFile("Exception at JobsHandler SendQuedEmails converting filepath to FILE. Exception: " + e.getMessage(), "", "", "", "");
                }
            }
            succ = objGlobalMethods.sendEmails(obj.toArr, obj.subjectstr, obj.bodystr, obj.attachmentfilename, myFile);
            if (succ) {
                objGlobalMethods.writeToFile(obj.subjectstr + " emailed to " + Arrays.toString(obj.toArr) + ".", "", "", "", "");
                if (obj.DeleteAttachementFile && myFile != null) {
                    //myFile.delete();

                    final Handler handler = new Handler();
                    final File ff = myFile;
                    handler.postDelayed(new Runnable() {
                        @Override
                        public void run() {
                            // Do something after 5s = 5000ms
                            ff.delete();
                        }
                    }, 10000);
                }
                delFirstobjEmailItem(updateJobInfoPref);
                processEmailsToSend(objGlobalMethods.getGcmPreferences(), updateJobInfoPref, true);
            } else {
                delFirstobjEmailItem(updateJobInfoPref); // purposely add here to monitor app behavior due keep attempt to send email n weird behavior like laggness etc appear. errors such as unknown smtp or file not found
                objGlobalMethods.writeToFile("JobsHandler SendQuedEmails not successful. Deleted from que. Subj: " + obj.EmailObjectiveTitle, "", "", "", "");
                processEmailsToSend(objGlobalMethods.getGcmPreferences(), updateJobInfoPref, false);
                /*startBackendRun15SecCounter();*/
                /*objGlobalMethods.writeToFile("JobsHandler SendQuedEmails not successful. Subj: " + obj.EmailObjectiveTitle, "", "", "", "");
                delFirstobjEmailItem(updateJobInfoPref);*/
            }
            //processEmailsToSend(objGlobalMethods.getGcmPreferences(), updateJobInfoPref);
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception at JobsHandler SendQuedEmails. Exception: " + e.getMessage(), "", "", "", "");
            processEmailsToSend(objGlobalMethods.getGcmPreferences(), updateJobInfoPref, false);
        }
    }

