    public static class processQueuedEmailsToSend0 extends AsyncTask<Void, Void, Integer> {
        public processQueuedEmailsToSend0() {

        }

        @Override
        protected Integer doInBackground(Void... params) {
            Integer asd = 0; //0 == 0 emails, 1 == some not sent, 2 == all sent
            objEmailItem obj = null;
            objEmailItem[] objAL;
            Gson gson = new Gson();
            SharedPreferences updateJobInfoPref;
            File myFile = null;
            boolean succ = false;
            int total = 0;
            int totalsent = 0;
            try {
                updateJobInfoPref = objGlobalMethods.getUpdateJobInfoPreferences();
                mutex.acquire();
                String EmailQuePrefStr = updateJobInfoPref.getString(objGlobalVariables.EmailQuePrefStr, "");
                mutex.release();
                if (!EmailQuePrefStr.isEmpty()) {
                    objAL = gson.fromJson(EmailQuePrefStr, objEmailItem[].class);
                    if (objAL != null && objAL.length > 0) {
                        List<objEmailItem> EmailQueAL = new ArrayList<objEmailItem>(Arrays.asList(objAL));
                        if (EmailQueAL != null && EmailQueAL.size() > 0) {
                            total = EmailQueAL.size();
                            for (int i = EmailQueAL.size() - 1; i >= 0; i--) {
                                obj = EmailQueAL.get(i);
                                myFile = null;
                                succ = false;
                                if (obj.sentAttempt < 3) {
                                    if (obj.attachmentfilename != null && !obj.attachmentfilename.isEmpty() && !obj.attachmentfilename.equals("") && obj.attachmentfilename != "") {
                                        try {
                                            myFile = new File(obj.attachmentfilename);
                                            if (!myFile.isAbsolute()) {
                                                myFile = null;
                                                objGlobalMethods.writeToFile("!myFile.isAbsolute for " + obj.subjectstr, "", "", "", "");
                                            } else {
                                                objGlobalMethods.writeToFile("myFile.isAbsolute for " + obj.subjectstr, "", "", "", "");
                                            }
                                        } catch (Exception e) {
                                            objGlobalMethods.writeToFile("Exception at JobsHandler processQueuedEmailsToSend0 doInBackground converting filepath to FILE. Exception: " + e.getMessage(), "", "", "", "");
                                        }
                                    }
                                    objGlobalMethods.writeToFile("Sending email with subj: " + obj.subjectstr + " to " + Arrays.toString(obj.toArr) + ".", "", "", "", "");
                                    succ = objGlobalMethods.sendEmails(obj.toArr, obj.subjectstr, obj.bodystr, obj.attachmentfilename, myFile);
                                    if (succ) {
                                        objGlobalMethods.writeToFile(obj.subjectstr + " emailed to " + Arrays.toString(obj.toArr) + ".", "", "", "", "");
                                        if (obj.DeleteAttachementFile && myFile != null) {
                                            myFile.delete();
                                        }
                                        EmailQueAL.remove(i);
                                        totalsent++;
                                        asd = asd == 1 ? 1 : 2;
                                    } else {
                                        EmailQueAL.get(i).setSentAttempt();
                                        asd = 1;
                                    }
                                } else {
                                    objGlobalMethods.writeToFile("Sending email with subj: " + obj.subjectstr + " to " + Arrays.toString(obj.toArr) + " ignored due 3rd attempt.", "", "", "", "");
                                    EmailQueAL.remove(i);
                                    asd = 1;
                                    totalsent++;
                                }
                            }
                        }

                        mutex.acquire();
                        SharedPreferences.Editor editor = updateJobInfoPref.edit();
                        if (EmailQueAL != null && EmailQueAL.size() > 0) {
                            objAL = EmailQueAL.toArray(new objEmailItem[EmailQueAL.size()]);
                            EmailQuePrefStr = gson.toJson(objAL);
                            if (EmailQuePrefStr.equals("[]")) {
                                EmailQuePrefStr = "";
                            }
                        } else {
                            EmailQuePrefStr = "";
                        }
                        editor.putString(objGlobalVariables.EmailQuePrefStr, EmailQuePrefStr);
                        editor.apply();
                        mutex.release();
                    }
                }
            } catch (Exception e) {
                asd = 0;
                objGlobalMethods.writeToFile("Exception at JobsHandler processQueuedEmailsToSend0 doInBackground. Exception: " + e.getMessage(), "", "", "", "");
            } finally {
                return asd;
            }
        }

        @Override
        protected void onPostExecute(final Integer success) {
            try {
                if (success == 0) {
                    objGlobalMethods.writeToFile("JobsHandler processQueuedEmailsToSend0 completed with 0 email sent out.", "", "", "", "");
                } else if (success == 1) {
                    objGlobalMethods.writeToFile("JobsHandler processQueuedEmailsToSend0 completed with some emails not sent.", "", "", "", "");
                } else if (success == 2) {
                    objGlobalMethods.writeToFile("JobsHandler processQueuedEmailsToSend0 completed with all emails sent.", "", "", "", "");
                }

            } catch (Exception e) {
                objGlobalMethods.writeToFile("Exception at JobsHandler processQueuedEmailsToSend0 onPostExecute. Exception: " + e.getMessage(), "", "", "", "");
            }
        }
    }

