    public static void doubleCheckUpdatePIPSQLiteNew(SharedPreferences gcmPref, SharedPreferences aUpdateJobInfoPreferences,
                                                     String aregid, String ausername, String auseridx) {
        //R6: prevent local job-status queue updates while RootGuard blocks this process
        if (RootGuard.blockOperation("JobsHandler.doubleCheckUpdatePIPSQLiteNew", null)) {
            return;
        }
        Gson gson = new Gson();
        objJobInfo[] JobInfoPIPAL = null;
        objJobInfo jobinfo;
        boolean existInQue;
        List<objUpdateJobInfoStatus> ListUpdateJobInfoStatusALAL = null;
        List<Long> AllPIPnotUpdatedJobsIDXList = null;
        int count = 0;
        int queCount = 0;
        List<Long> JobsIDXList = null;
        Long[] JobsIDXsArr = null;
        long JobsIDX = 0;
        try {
            ListUpdateJobInfoStatusALAL = JobsHandler.getJobInfoListInQueForStatusUpdate(aUpdateJobInfoPreferences);
            AllPIPnotUpdatedJobsIDXList = DAO_Jobs.getAllPIPnotUpdatedJobsIDX();

            Location lastknownlocation = objGlobalMethods.getLastKnownLocationForJobUpdate();
            int Accuracy = Math.round(lastknownlocation.getAccuracy() * 100);

            if (AllPIPnotUpdatedJobsIDXList != null && AllPIPnotUpdatedJobsIDXList.size() > 0) {
                for (int i = 0; i <= AllPIPnotUpdatedJobsIDXList.size() - 1; i++) {
                    existInQue = false;
                    if (ListUpdateJobInfoStatusALAL != null && ListUpdateJobInfoStatusALAL.size() > 0) {
                        for (int j = 0; j <= ListUpdateJobInfoStatusALAL.size() - 1; j++) {
                            if (AllPIPnotUpdatedJobsIDXList.get(i) == ListUpdateJobInfoStatusALAL.get(j).JobsIDX) {
                                existInQue = true;
                                break;
                            }
                        }
                    }

                    if (!existInQue) {
                        if (JobsIDXList == null)
                            JobsIDXList = new ArrayList<>();

                        JobsIDX = AllPIPnotUpdatedJobsIDXList.get(i);
                        if (JobsIDX > 0 && !JobsIDXList.contains(JobsIDX))
                            JobsIDXList.add(JobsIDX);
                    }
                }
            }

            if (JobsIDXList != null && JobsIDXList.size() > 0) {
                String jobsidxs = Arrays.toString(JobsIDXList.toArray());
                objGlobalMethods.writeToFile("From doubleCheckUpdatePIPSQLiteNew, Update job status to 103", "JobsIDX: " +
                        jobsidxs, "103", "", "");

                JobsIDXsArr = JobsIDXList.toArray(new Long[JobsIDXList.size()]);

                Date dt = new Date();
                Long l = dt.getTime();
                String timestampstr = "/Date(" + l + ")/";

                JobsHandler.addUpdateJobInfoStatusWithGPSMassQueALPrefs(aUpdateJobInfoPreferences, aregid, JobsIDXsArr, 103,
                        timestampstr, "", "", lastknownlocation.getLatitude(), lastknownlocation.getLongitude(),
                        Accuracy, "");
                count += 1;

            }

            queCount = JobsHandler.returnNumberOfQueToSend(aUpdateJobInfoPreferences);
            count += queCount;

            if (count > 0) {
                DrawerMainActivity.handler.postDelayed(DrawerMainActivity.runnable, 2000);
            }
        } catch (Exception e) {
            e.printStackTrace();
            objGlobalMethods.writeToFile("Backend ended due Exception at JobsHandler doubleCheckUpdatePIPSQLiteNew. Exception: " + e.getMessage().toString(), "", "", "", "");
            backEndIsRunning = false;
            startBackendRun15SecCounter();
        }
    }

    public static void doubleCheckUpdatePIPSQLite(SharedPreferences gcmPref, SharedPreferences aUpdateJobInfoPreferences,
                                                  String aregid, String ausername, String auseridx, boolean isCalledFromResync) {
        String JobInfoJsonStr = "";
        Gson gson = new Gson();
        objJobInfo[] JobInfoPIPAL = null;
        objJobInfo jobinfo;
        boolean existInQue;
        List<objUpdateJobInfoStatus> ListUpdateJobInfoStatusALAL = null;
        List<Long> AllPIPnotUpdatedJobsIDXList = null;
        int count = 0;
        int queCount = 0;
        try {
            JobInfoJsonStr = getJobInfoJsonStr(true, gcmPref);
            ListUpdateJobInfoStatusALAL = JobsHandler.getJobInfoListInQueForStatusUpdate(aUpdateJobInfoPreferences);
            AllPIPnotUpdatedJobsIDXList = DAO_Jobs.getAllPIPnotUpdatedJobsIDX();

            Location lastknownlocation = objGlobalMethods.getLastKnownLocationForJobUpdate();
            int Accuracy = Math.round(lastknownlocation.getAccuracy() * 100);

            if (AllPIPnotUpdatedJobsIDXList != null && AllPIPnotUpdatedJobsIDXList.size() > 0) {
                for (int i = 0; i <= AllPIPnotUpdatedJobsIDXList.size() - 1; i++) {
                    existInQue = false;
                    if (ListUpdateJobInfoStatusALAL != null && ListUpdateJobInfoStatusALAL.size() > 0) {
                        for (int j = 0; j <= ListUpdateJobInfoStatusALAL.size() - 1; j++) {
                            if (AllPIPnotUpdatedJobsIDXList.get(i) == ListUpdateJobInfoStatusALAL.get(j).JobsIDX) {
                                existInQue = true;
                                break;
                            }
                        }
                    }

                    if (!existInQue) {
                        Date dt = new Date();
                        Long l = dt.getTime();
                        String timestampstr = "/Date(" + l + ")/";
                        objGlobalMethods.writeToFile("From doubleCheckUpdatePIPSQLite, Update job status to 103", String.valueOf(AllPIPnotUpdatedJobsIDXList.get(i)), "103", ausername, auseridx);
                        JobsHandler.addUpdateJobInfoStatusWithGPSQueALPrefs(aUpdateJobInfoPreferences, aregid, AllPIPnotUpdatedJobsIDXList.get(i), 103, timestampstr, "", "",
                                lastknownlocation.getLatitude(), lastknownlocation.getLongitude(), Accuracy, "");

                        count += 1;
                    }

                }
            }

            queCount = JobsHandler.returnNumberOfQueToSend(aUpdateJobInfoPreferences);
            count += queCount;

            if (count > 0) {
                DrawerMainActivity.handler.postDelayed(DrawerMainActivity.runnable, 2000);
            }
        } catch (Exception e) {
            e.printStackTrace();
            Date dt = new Date();
            objGlobalMethods.writeToFile("Backend ended due Exception at JobsHandler doubleCheckUpdatePIPSQLite. Exception: " + e.getMessage().toString(), "", "", "", "");
            backEndIsRunning = false;
            /*DrawerMainActivity.stopRunnable();
            DrawerMainActivity.postphoneRunnable();*/
            startBackendRun15SecCounter();
        }
    }
