    public static class SendJobMessage extends AsyncTask<Void, Void, Boolean> {
        private final String ARegID;
        private final ChatMessage Message;
        private final String AUserIDX;
        private final String AJobsIDX;
        private final SharedPreferences AupdateJobInfoPref;
        private final String AUTC;
        private final double ALat;
        private final double ALng;
        private final SharedPreferences GcmPref;

        SendJobMessage(String aARegID, ChatMessage aMessage, String aAUserIDX, String aAJobsIDX, SharedPreferences aAupdateJobInfoPref, String aAUTC, double aALat, double aALng, SharedPreferences aGcmPref) {
            this.ARegID = aARegID;
            this.Message = aMessage;
            this.AUserIDX = aAUserIDX;
            this.AJobsIDX = aAJobsIDX;
            this.AupdateJobInfoPref = aAupdateJobInfoPref;
            this.AUTC = aAUTC;
            this.ALat = aALat;
            this.ALng = aALng;
            this.GcmPref = aGcmPref;
        }

        @Override
        //Make Progress Bar visible
        protected void onPreExecute() {

        }

        @Override
        protected Boolean doInBackground(Void... params) {
            return WebService.SendJobMessageA(ARegID, Message.getMessageText().toString(), AUserIDX, AJobsIDX, AUTC, ALat, ALng);
        }

        @Override
        //Once WebService returns response
        protected void onPostExecute(final Boolean success) {
            int queCount = 0;
            try {
                queCount = returnNumberOfQueToSend(AupdateJobInfoPref);
                if (success != null) {
                    if (!success) {
                        //if result return false, stop current activity and postpone, add back to que
                        MessageQue objMessageQue = new MessageQue(ARegID, Message, AUserIDX, AJobsIDX);
                        addSendMessageQuePrefs2(AupdateJobInfoPref, objMessageQue);
                        backEndIsRunning = false;
                        objGlobalMethods.writeToFile("JobsHandler.SendJobMessageA returns false, add back to Que. ", "", "", "", "");
                        /*DrawerMainActivity.stopRunnable();
                        DrawerMainActivity.postphoneRunnable();*/
                        startBackendRun15SecCounter();
                    } else {
                        //if result return true, do nothing
                        objGlobalMethods.writeToFile("JobsHandler.SendJobMessageA successful.", "", "", "", "");
                        DAO_Jobs.updateChatMessageStatus(Message.getID(), com.xdel.luke.messagingClasses.Status.DELIVERED.ordinal());
                        if (currentActivity != null && currentActivity.getClass() == Messaging.class) {
                            final Messaging act = (Messaging) currentActivity;
                            act.runOnUiThread(new Runnable() {
                                public void run() {
                                    act.updateListViewWithSent2();
                                }
                            });
                        }

                        if (queCount > 0) {
                            processUpdateJobInfoStatusQue2(GcmPref, AupdateJobInfoPref);
                        } else {
                            processSendMessage2(GcmPref, AupdateJobInfoPref);
                        }
                    }
                } else {
                    //if error
                    MessageQue objMessageQue = new MessageQue(ARegID, Message, AUserIDX, AJobsIDX);
                    addSendMessageQuePrefs2(AupdateJobInfoPref, objMessageQue);
                    backEndIsRunning = false;
                    objGlobalMethods.writeToFile("JobsHandler.SendJobMessageA returns null, add back to Que. ", "", "", "", "");
                    /*DrawerMainActivity.stopRunnable();
                    DrawerMainActivity.postphoneRunnable();*/
                    startBackendRun15SecCounter();
                }
            } catch (Exception e) {
                backEndIsRunning = false;
                //String s = JobsHandler.getStackTraceString(e);
                objGlobalMethods.writeToFile("Exception caught at JobsHandler.SendJobMessageA onPostExecute, not add back to Que. " + e.toString(), "", "", "", "");
                /*DrawerMainActivity.stopRunnable();
                DrawerMainActivity.postphoneRunnable();*/
                startBackendRun15SecCounter();
            }
        }
    }

