    //checked
    public static void checkForceLogOut() {
        String forceLogOutBooleanString;
        Context ctx = myApp.getAppContext();
        SharedPreferences GcmPreferences = objGlobalMethods.getGcmPreferences();
        SharedPreferences UpdateJobInfoPreferences = objGlobalMethods.getUpdateJobInfoPreferences();
        int queCount;
        String[] UsernamePwd = new String[4];

        try {
            forceLogOutBooleanString = objGlobalMethods.getGCMPrefs(GcmPreferences, "forceLogOutBooleanString");
            //forceLogOutBooleanString = "true";
            if (!forceLogOutBooleanString.equals("") && forceLogOutBooleanString.equals("true")) {
                queCount = JobsHandler.returnNumberOfQueToSend(UpdateJobInfoPreferences);
                if (queCount > 0) {
                    backendRun(GcmPreferences, UpdateJobInfoPreferences);
                } else {
                    UsernamePwd = objGlobalMethods.getLoginUsernamePwd(GcmPreferences);
                    final String username = UsernamePwd[0];
                    final String pwd = UsernamePwd[1];
                    if (currentActivity != null && currentActivity.getClass() == DrawerMainActivity.class) {
                        final DrawerMainActivity act = (DrawerMainActivity) currentActivity;
                        pdCheck = new ProgressDialog(act);
                    } else if (currentActivity != null && currentActivity.getClass() == DrawerMain2Activity.class) {
                        final DrawerMain2Activity act = (DrawerMain2Activity) currentActivity;
                        pdCheck = new ProgressDialog(act);
                    } else if (currentActivity != null && currentActivity.getClass() == AddressListNewActivity.class) {
                        final AddressListNewActivity act = (AddressListNewActivity) currentActivity;
                        pdCheck = new ProgressDialog(act);
                    } else if (currentActivity != null && currentActivity.getClass() == JobsListGroupActivity.class) {
                        final JobsListGroupActivity act = (JobsListGroupActivity) currentActivity;
                        pdCheck = new ProgressDialog(act);
                    } else if (currentActivity != null && currentActivity.getClass() == JobInfoActivity.class) {
                        final JobInfoActivity act = (JobInfoActivity) currentActivity;
                        pdCheck = new ProgressDialog(act);
                    } else if (currentActivity != null && currentActivity.getClass() == ChangePwdActivity.class) {
                        final ChangePwdActivity act = (ChangePwdActivity) currentActivity;
                        pdCheck = new ProgressDialog(act);
                    } else if (currentActivity != null && currentActivity.getClass() == DigitalAgreementActivity.class) {
                        final DigitalAgreementActivity act = (DigitalAgreementActivity) currentActivity;
                        pdCheck = new ProgressDialog(act);
                    }

                    objGlobalMethods.writeToFile("Force Logout.", "", "", "", "");
                    if (pdCheck != null) {
                        pdCheck.setProgressStyle(ProgressDialog.STYLE_SPINNER);
                        pdCheck.setCanceledOnTouchOutside(false);
                        pdCheck.setMessage("Logging you out now.");
                    }
                    final Thread t = new Thread() {
                        @Override
                        public void run() {
                            checkForAttachmentToEmailOut3(username, pwd);
                        }
                    };
                    t.start();
                    //checkForAttachmentToEmailOut3(username, pwd);
                }
            } else if (forceLogOutBooleanString.equals("") || forceLogOutBooleanString.equals("false")) {
                objGlobalMethods.setGCMPrefs(GcmPreferences, "forceLogOutBooleanString", "false");
                return;
            }
        } catch (Exception e) {
            objGlobalMethods.setGCMPrefs(GcmPreferences, "forceLogOutBooleanString", "false");
            return;
        }
    }

    //checked
    public static class checkForAttachmentToEmailOut extends AsyncTask<Void, Void, File> {
        private final String username;
        private final String pwd;

        public checkForAttachmentToEmailOut(String ausername, String apwd) {
            this.username = ausername;
            this.pwd = apwd;
        }

        @Override
        //Make Progress Bar visible
        protected void onPreExecute() {
            try {
                /*if (pdCheck == null && (currentActivity != null && currentActivity.getClass() == LeaveActivity.class)) {
                    pdCheck = new ProgressDialog((LeaveActivity) myApp.currentActivity);
                    pdCheck.setProgressStyle(ProgressDialog.STYLE_SPINNER);
                    pdCheck.setCanceledOnTouchOutside(false);
                    pdCheck.setMessage("Logging you out now.");
                }
                if (pdCheck != null) {
                    pdCheck.show();
                }*/
            } catch (Exception e) {
                String s = getStackTraceString(e);
                objGlobalMethods.writeToFile("Exception at JobsHandler checkForAttachmentToEmailOut onPreExecute. Exception: " + e.getMessage() + "\nStack: " + s, "", "", "", "");
            }
        }

        @Override
        protected File doInBackground(Void... params) {

            try {
                Date dt = new Date();
                SimpleDateFormat formatter = new SimpleDateFormat("ddMMyyyy");
                String Filenamedtstr = "";
                Filenamedtstr = formatter.format(dt);
                File externalStorageDir = Environment.getExternalStorageDirectory();
                attachment = new File(externalStorageDir, Filenamedtstr + "_log.txt");
            } catch (Exception e) {
                attachment = null;
            }

            return null;
        }

        @Override
        //Once WebService returns response
        protected void onPostExecute(final File success) {
            String attachmentfilename = "";
            if (pdCheck != null) {
                pdCheck.dismiss();
            }
            try {
                if (attachment.exists()) {
                    attachmentfilename = attachment.getAbsolutePath().toString();
                    if (!attachmentfilename.equals("")) {

                        Mail m = new Mail("luke@xdel.com", "XDel2015");
                        objGlobalMethods.sendEmail sendmail = new objGlobalMethods.sendEmail(m, attachmentfilename, "", "Luke report from " + username + ".", attachment);
                        sendmail.execute();
                    }
                }
            } catch (Exception e) {
                objGlobalMethods.writeToFile("Exception caught at JobsHandler checkForAttachmentToEmailOut. " + e.getMessage().toString(), "", "", "", "");
            }

            LogOutWSCall task = new LogOutWSCall(username, pwd);
            task.execute();
        }
    }

