    public static void ManualForceLogout() {
        int queCount = 0;
        SharedPreferences GcmPreferences, UpdateJobInfoPreferences;
        try {
            UpdateJobInfoPreferences = objGlobalMethods.getUpdateJobInfoPreferences();
            queCount = returnNumberOfQueToSend(UpdateJobInfoPreferences);
            if (queCount == 0) {
                GcmPreferences = objGlobalMethods.getGcmPreferences();
                objGlobalMethods.setGCMPrefs(GcmPreferences, "disablePush", "true");
                objGlobalMethods.writeToFile("Manual force logout performed after idling for 3 hours or more.", "", "", "", "");
                /*BackToLoginPageStandardToDO(GcmPreferences, UpdateJobInfoPreferences);
                actFinish();*/
                String[] UsernamePwd = new String[4];
                UsernamePwd = objGlobalMethods.getLoginUsernamePwd(GcmPreferences);
                String prevLoginUserName = objGlobalMethods.getGCMPrefs(GcmPreferences, "prevLoginUserName");
                final String username = objGlobalMethods.IsEmptyString(UsernamePwd[0]) && !objGlobalMethods.IsEmptyString(prevLoginUserName) ? prevLoginUserName
                        : !objGlobalMethods.IsEmptyString(UsernamePwd[0]) ? UsernamePwd[0] : "";
                final String pwd = UsernamePwd[1];
                final Thread t = new Thread() {
                    @Override
                    public void run() {
                        checkForAttachmentToEmailOut3(username, pwd);
                    }
                };
                t.start();
            }
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception at JobsHandler ManualForceLogout. Exception: " + e.getMessage().toString(), "", "", "", "");
        }
    }

