    public static void updateNewJobStatusWithGPS3(String ARegID, long AJobsIDX, long AStatusCodeIDX, String ARecipient, String ARemarks, String AUTC,
                                                  String ABase64String, double ALat, double ALng, int Accuracy, final SharedPreferences AupdateJobInfoPref, final SharedPreferences GcmPref, boolean callFromPush) {
        Boolean success = null;
        String[] UsernamePwd = new String[4];
        String username = "", useridx = "";

        try {
            ARegID = objGlobalMethods.getRegistrationIdOnly();
            success = WebService.UpdateJobStatusCodeWithGPSAccuracy(ARegID, AJobsIDX, AStatusCodeIDX, ARecipient, ARemarks, AUTC, ALat, ALng, Accuracy, "L2_UpdateJobStatusA");

            UsernamePwd = objGlobalMethods.getLoginUsernamePwd(GcmPref);
            username = UsernamePwd[0];
            useridx = UsernamePwd[2];
            setCurrDTasPrevDTforIdlingCheck();
            if (success == null) {
                objGlobalMethods.writeToFile("Error invoking L2_UpdateJobStatusA, adding back to que. Driver: " + username + ", DriverIDX: " + useridx,
                        "JobsIDX: " + String.valueOf(AJobsIDX), "Submitted StatusCodeIDX: " + String.valueOf(AStatusCodeIDX) + ", ARegID = " + ARegID, username, useridx);
                backEndIsRunning = false;
                objGlobalMethods.writeToFile("Backend ended due Error invoking L2_UpdateJobStatusA for JobsIDX: " + String.valueOf(AJobsIDX) + ", Submitted StatusCodeIDX: "
                                + String.valueOf(AStatusCodeIDX) + ". Ending JobsHandler updateNewJobStatusWithGPS3.",
                        "", "", username, useridx);

                //setCurrDTasPrevDTforIdlingCheck();
                startBackendRun15SecCounter();
            } else if (success) {
                //if result return true, do nothing
                objGlobalMethods.writeToFile("Update job status successful. Driver: " + username + ", DriverIDX: " + useridx,
                        "JobsIDX: " + String.valueOf(AJobsIDX), "Submitted StatusCodeIDX: " + String.valueOf(AStatusCodeIDX) +
                                ". Ending JobsHandler updateNewJobStatusWithGPS3, calling processUpdateJobInfoStatusQue2.", username, useridx);

                removeUpdateJobInfoStatusQue(AupdateJobInfoPref, AJobsIDX);
                if (AStatusCodeIDX != 368 && AStatusCodeIDX != 369 && AStatusCodeIDX != 388) {
                    DAO_Jobs.updateJobsStatusCodeIDX(AJobsIDX, AStatusCodeIDX);
                }

                /*if (actionCount == null)
                    actionCount = 0;
                actionCount += 1;*/
                processUpdateJobInfoStatusQue2(GcmPref, AupdateJobInfoPref);
            } else if (!success) {
                //if result return false, stop current activity and postpone, do not add back to que
                objGlobalMethods.writeToFile("L2_UpdateJobStatusA return false, not add back to que. Driver: " + username + ", DriverIDX: " + useridx,
                        "JobsIDX: " + String.valueOf(AJobsIDX), "Submitted StatusCodeIDX: " + String.valueOf(AStatusCodeIDX) + ", ARegID = " + ARegID, username, useridx);

                sendErrorEmail("L2_UpdateJobStatus return false, not add back to que. Driver: " + username + ", DriverIDX: " + useridx +
                        ", JobsIDX: " + String.valueOf(AJobsIDX) + ", Submitted StatusCodeIDX: " + String.valueOf(AStatusCodeIDX));

                removeUpdateJobInfoStatusQue(AupdateJobInfoPref, AJobsIDX);
                backEndIsRunning = false;
                objGlobalMethods.writeToFile("Backend ended due L2_UpdateJobStatusA return false for JobsIDX: " + String.valueOf(AJobsIDX) + ", Submitted StatusCodeIDX: "
                                + String.valueOf(AStatusCodeIDX) + ". Ending JobsHandler updateNewJobStatusWithGPS3.",
                        "", "", username, useridx);

                //setCurrDTasPrevDTforIdlingCheck();
                startBackendRun15SecCounter();
            }
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception caught at JobsHandler updateNewJobStatusWithGPS3. Exception: " + e.toString(),
                    "JobsIDX: " + String.valueOf(AJobsIDX), "Submitted StatusCodeIDX: " + String.valueOf(AStatusCodeIDX) + ", ARegID = " + ARegID, "", "");

            String s = getStackTraceString(e);
            sendErrorEmail("Exception caught at update job status onPostExecute, not add back to que. Driver: " + username + ", DriverIDX: " + useridx +
                    ", JobsIDX: " + String.valueOf(AJobsIDX) + ", Submitted StatusCodeIDX: " + String.valueOf(AStatusCodeIDX) + ", ARegID = " + ARegID + "\n" + e.toString() + " Stack: " + s);

            removeUpdateJobInfoStatusQue(AupdateJobInfoPref, AJobsIDX);
            backEndIsRunning = false;
            objGlobalMethods.writeToFile("Backend ended due Exception caught at updateNewJobStatusWithGPS3 onPostExecute for JobsIDX: " + String.valueOf(AJobsIDX)
                    + ", Submitted StatusCodeIDX: " + String.valueOf(AStatusCodeIDX) + ".", "", "", username, useridx);
            setCurrDTasPrevDTforIdlingCheck();
            startBackendRun15SecCounter();
        }
    }

