    public static void updateLeaveApplication(objLeaveRecordSubmit LeaveRecordSubmit, SharedPreferences AupdateJobInfoPref, SharedPreferences GcmPref) {
        Boolean success = null;
        objLeaveRecord res = null;
        String[] UsernamePwd = new String[4];
        String username = "", useridx = "";
        int queCount = 0;
        String UpdateLeaveApplicationRequeCountPrefStr;
        int UpdateLeaveApplicationRequeCount = 0;
        String ARegID;
        try {
            ARegID = objGlobalMethods.getRegistrationIdOnly();
            res = WebService.UpdateLeaveApplication(ARegID, LeaveRecordSubmit);

            queCount = returnNumberOfQueToSend(AupdateJobInfoPref);
            UsernamePwd = objGlobalMethods.getLoginUsernamePwd(GcmPref);
            username = UsernamePwd[0];
            useridx = UsernamePwd[2];
            setCurrDTasPrevDTforIdlingCheck();
            UpdateLeaveApplicationRequeCountPrefStr = objGlobalMethods.getGCMPrefs(GcmPref, "UpdateLeaveApplicationRequeCountPrefStr");
            try {
                UpdateLeaveApplicationRequeCount =
                        !UpdateLeaveApplicationRequeCountPrefStr.isEmpty() &&
                                !UpdateLeaveApplicationRequeCountPrefStr.equals("") &&
                                !UpdateLeaveApplicationRequeCountPrefStr.equals("0") ? Integer.parseInt(UpdateLeaveApplicationRequeCountPrefStr) : 0;
            } catch (Exception e) {
                UpdateLeaveApplicationRequeCount = 0;
            }

            if (res == null) {
                objGlobalMethods.writeToFile("Error invoking L2_UpdateLeaveApplication, adding back to que.",
                        "", "", username, useridx);

                if (UpdateLeaveApplicationRequeCount == 10) {
                    //disregard, ignore, dun add back to que
                } else if (UpdateLeaveApplicationRequeCount < 10) {
                    UpdateLeaveApplicationRequeCount++;
                    objGlobalMethods.setGCMPrefs(GcmPref, "UpdateLeaveApplicationRequeCountPrefStr", String.valueOf(UpdateLeaveApplicationRequeCount));
                    addUpdateLeaveApplicationQueALPrefs(AupdateJobInfoPref, LeaveRecordSubmit);
                    sendErrorEmail("L2_UpdateLeaveApplication returns null, adding back to que. Driver:" + username + ", DriverIDX:" + useridx);
                }

                backEndIsRunning = false;
                objGlobalMethods.writeToFile("Backend ended due Error invoking L2_UpdateLeaveApplication", "", "", username, useridx);

                //setCurrDTasPrevDTforIdlingCheck();
                startBackendRun15SecCounter();
            } else if (res != null && res.IDX > 0) {
                //else if (res != null && res.IDX > 0 && res.Units > 0) {
                //if result return true, do nothing
                objGlobalMethods.writeToFile("L2_UpdateLeaveApplication successful, Units: " + String.valueOf(res.Units), "", "", username, useridx);

                objGlobalMethods.setGCMPrefs(GcmPref, "UpdateLeaveApplicationRequeCountPrefStr", "0");

                if (myApp.currentActivity != null && myApp.currentActivity.getClass() == LeaveActivity.class) {
                    final LeaveActivity act = (LeaveActivity) myApp.currentActivity;
                    act.runOnUiThread(new Runnable() {
                        public void run() {
                            // Notifiy activity
                            act.refresh();
                        }
                    });
                }

                if (queCount > 0) {
                    processUpdateJobInfoStatusQue2(GcmPref, AupdateJobInfoPref);
                } else {
                    processUpdateLeaveApplication(GcmPref, AupdateJobInfoPref);
                }
            } else if (res != null && res.IDX == 0) {
                //else if (res != null && (res.IDX == 0 || (res.IDX > 0 && res.Units == 0))) {
                String msg = "";
                msg = "L2_UpdateLeaveApplication not process properly by Backend, IDX == 0, adding back to que.";

                objGlobalMethods.writeToFile(msg, "", "", username, useridx);

                if (UpdateLeaveApplicationRequeCount == 10) {
                    //disregard, ignore, dun add back to que
                    msg = "L2_UpdateLeaveApplication not process after 10 attempts. Not add back to que.";
                } else {
                    UpdateLeaveApplicationRequeCount++;
                    objGlobalMethods.setGCMPrefs(GcmPref, "UpdateLeaveApplicationRequeCountPrefStr", String.valueOf(UpdateLeaveApplicationRequeCount));
                    addUpdateLeaveApplicationQueALPrefs(AupdateJobInfoPref, LeaveRecordSubmit);
                    sendErrorEmail(msg + " Driver:" + username + ", DriverIDX:" + useridx);
                }

                backEndIsRunning = false;

                //setCurrDTasPrevDTforIdlingCheck();
                startBackendRun15SecCounter();
            } else if (res != null && res.IDX < 0) {
                //rejected
                objGlobalMethods.writeToFile("L2_UpdateLeaveApplication returns negative IDX. Leave Application rejected.", "", "", username, useridx);
                if (queCount > 0) {
                    processUpdateJobInfoStatusQue2(GcmPref, AupdateJobInfoPref);
                } else {
                    processUpdateLeaveApplication(GcmPref, AupdateJobInfoPref);
                }
            }
        } catch (Exception e) {
            sendErrorEmail("Exception caught at JobsHandler updateLeaveApplication, not add back to que. Driver: " + username + ", DriverIDX: " + useridx + "\n" + e.toString());
            backEndIsRunning = false;
            objGlobalMethods.writeToFile("Backend ended due Exception caught at JobsHandler updateLeaveApplication.", "", "", username, useridx);
            setCurrDTasPrevDTforIdlingCheck();
            startBackendRun15SecCounter();
        }
    }

