    public static void RegetSpecificJobCategoryCount03SQLite(String regid, SharedPreferences GCMprefs, SharedPreferences updateJobInfoPref, int RetrieveType,
                                                             String HashName, String JobsIDXarrName, String JobInfoJsonPrefName, String JobsCountName, int nextRetrieveType, String[] aJobsCategoryHash) {
        Date dt = new Date();
        ArrayList arr = null;
        ArrayList<Long> OtpLockedJobsIdxAL = null;
        int count;
        String cHashstr;
        String JobsIDXarrJsonStr = "";
        String newhash = "";
        String syshash = "";
        Gson gson = new Gson();
        final int finalRetrieveType = RetrieveType;
        Long[] JobsIDXarr = null;
        objJobInfo[] JobInfoAL = null;
        String s = "";
        int JobsIDXarrsize = 0;
        int JobInfoALsize = 0;

        try {
            arr = JobsHandler.ReGetDriverJobsArrayList(regid, RetrieveType, "L2_GetDriverJobsIDX");

            if (arr != null) {
                JobsIDXarr = arr != null && arr.size() > 0 && arr.get(0) != null ? (Long[]) arr.get(0) : null;
                JobInfoAL = arr != null && arr.size() == 3 && arr.get(2) != null ? (objJobInfo[]) arr.get(2) : null;

                if (JobsIDXarr != null && JobInfoAL != null) {
                    Arrays.sort(JobsIDXarr);
                    for (int v = 0; v <= JobsIDXarr.length - 1; v++) {
                        s += "[" + String.valueOf(JobsIDXarr[v]) + "]";
                    }
                    if (!s.trim().equals("")) {
                        try {
                            cHashstr = SHA1(s);
                        } catch (Exception e) {
                            objGlobalMethods.writeToFile("Exception at DrawerMainActivity GetDriverJobsCountSQLite doInBackground cHashstr conversion. Exception: " + e.getMessage(), "", "", "", "");
                            s = "";
                            cHashstr = "";
                        }

                        try {
                            objJobInfo[] newExtraJobInfoAL;
                            List<objJobInfo> newExtraJobInfoList;
                            List<Long> JobsIDXsToBeDeletedList = null;
                            List<objJobInfo> JobInfoToBeInsertedList = null;

                            newExtraJobInfoAL = WebService.GetDriverJobsInfoAL(regid, JobsIDXarr, "L2_GetDriverJobInfo");
                            if (newExtraJobInfoAL != null && newExtraJobInfoAL.length > 0) {
                                newExtraJobInfoList = new ArrayList<objJobInfo>(Arrays.asList(newExtraJobInfoAL));
                                List<Long> dbJobsIDXsList = DAO_Jobs.getAlldbObjJobsIDXsPerCategory(finalRetrieveType);

                                //create list of jobs to be inserted to db for this category
                                for (int x = 0; x <= newExtraJobInfoList.size() - 1; x++) {
                                    objJobInfo ji = newExtraJobInfoList.get(x);

                                    if (!dbJobsIDXsList.contains(ji.JobsIDX) && JobInfoToBeInsertedList != null) {
                                        //add
                                        JobInfoToBeInsertedList.add(ji);
                                    } else if (!dbJobsIDXsList.contains(ji.JobsIDX) && JobInfoToBeInsertedList == null) {
                                        //add
                                        JobInfoToBeInsertedList = new ArrayList<>();
                                        JobInfoToBeInsertedList.add(ji);
                                    }
                                }

                                //create list of JobsIDXs to be deleted from db for this category
                                for (int x = 0; x <= dbJobsIDXsList.size() - 1; x++) {
                                    Long newJobsIDXlongArr[] = new Long[JobsIDXarr.length];
                                    int i = 0;
                                    for (long temp : JobsIDXarr) {
                                        newJobsIDXlongArr[i++] = temp;
                                    }
                                    List<Long> newJobsIDXlongArrList = new ArrayList<Long>(Arrays.asList(newJobsIDXlongArr));

                                    if (!newJobsIDXlongArrList.contains(dbJobsIDXsList.get(x)) && JobsIDXsToBeDeletedList != null) {
                                        //remove
                                        JobsIDXsToBeDeletedList.add(dbJobsIDXsList.get(x));
                                    } else if (!newJobsIDXlongArrList.contains(dbJobsIDXsList.get(x)) && JobsIDXsToBeDeletedList == null) {
                                        JobsIDXsToBeDeletedList = new ArrayList<>();
                                        JobsIDXsToBeDeletedList.add(dbJobsIDXsList.get(x));
                                    }
                                }

                                if (JobsIDXsToBeDeletedList != null && JobsIDXsToBeDeletedList.size() > 0) {
                                    //delete all these record from db based on cattypeid n jobsidx
                                    String[] JobsIDXsToBeDeletedStrArr = new String[JobsIDXsToBeDeletedList.size()];
                                    for (int i = 0; i < JobsIDXsToBeDeletedList.size(); i++)
                                        JobsIDXsToBeDeletedStrArr[i] = String.valueOf(JobsIDXsToBeDeletedList.get(i));

                                    String joinedString = "";
                                    for (int i = 0; i <= JobsIDXsToBeDeletedList.size() - 1; i++) {
                                        if (i == JobsIDXsToBeDeletedList.size() - 1) {
                                            joinedString += String.valueOf(JobsIDXsToBeDeletedList.get(i));
                                        } else {
                                            joinedString += String.valueOf(JobsIDXsToBeDeletedList.get(i)) + ",";
                                        }
                                    }
                                    DAO_Jobs.deleteJobByIDXrange(joinedString);
                                }

                                if (JobInfoToBeInsertedList != null && JobInfoToBeInsertedList.size() > 0) {
                                    //insert all these record into db base on this cattypeid
                                    for (int i = 0; i <= JobInfoToBeInsertedList.size() - 1; i++) {
                                        objJobInfo ji = JobInfoToBeInsertedList.get(i);
                                        String JobInfoJsonStr = gson.toJson(ji);
                                        DAO_Jobs.insertJobs(ji, finalRetrieveType, JobInfoJsonStr);
                                    }
                                }

                                setCategoryHashes(GCMprefs, HashName, cHashstr);
                                if (RetrieveType >= 0) {
                                    if (currentActivity != null && currentActivity.getClass() == DrawerMainActivity.class) {
                                        final DrawerMainActivity act = (DrawerMainActivity) currentActivity;
                                        act.runOnUiThread(new Runnable() {
                                            public void run() {
                                                act.updateListRowPerCategory(finalRetrieveType, true);
                                            }
                                        });
                                    } else if (myApp.currentActivity != null && myApp.currentActivity.getClass() == DrawerMain2Activity.class) {
                                        final DrawerMain2Activity act = (DrawerMain2Activity) myApp.currentActivity;
                                        act.runOnUiThread(new Runnable() {
                                            @Override
                                            public void run() {
                                                act.refreshrv(false);
                                            }
                                        });
                                    }
                                }

                            } else {
                                //do nothing, do not touch existing system values, wait for user to refresh
                            }
                        } catch (Exception e) {
                            //do nothing, do not touch existing system values
                            objGlobalMethods.writeToFile("Exception caught at JobsHandler RegetSpecificJobCategoryCount03SQLite with RetrieveType: " + String.valueOf(RetrieveType) + ". Exception: "
                                    + e.getMessage().toString(), "", "", "", "");
                        }
                    } else {
                        objGlobalMethods.writeToFile("JobsHandler RegetSpecificJobCategoryCount03SQLite's ReGetDriverJobsArrayLists is not null but conversion of JobsIDX to hash is empty when RetrieveType = "
                                + String.valueOf(RetrieveType) + ". Call resetCategoryHashes.", "", "", "", "");
                        //do not anyhow delete below 2 lines.
                        setCategoryHashes(GCMprefs, HashName, "");
                        DAO_Jobs.deleteJobsByCatTypeID(finalRetrieveType);
                    }
                }
            } else {
                objGlobalMethods.writeToFile("JobsHandler RegetSpecificJobCategoryCount03SQLite's ReGetDriverJobsArrayLists is null when RetrieveType = "
                        + String.valueOf(RetrieveType) + ". Call resetCategoryHashes.", "", "", "", "");
                //do not anyhow delete below 2 lines.
                /*setCategoryHashes(GCMprefs, HashName, "");
                DAO_Jobs.deleteJobsByCatTypeID(finalRetrieveType);*/
            }

        } catch (Exception e) {
            String stack = getStackTraceString(e);
            objGlobalMethods.writeToFile("Exception at JobsHandler RegetSpecificJobCategoryCount03SQLite. Exception: " + e.getMessage() + "\nStack: " + stack, "", "", "", "");
        } finally {
            if (nextRetrieveType != -1) {
                objGlobalMethods.writeToFile("JobsHandler RegetSpecificJobCategoryCount03SQLite calling testresync when nextRetrieveType = " + String.valueOf(nextRetrieveType), "", "", "", "");
                //testresync(aJobsCategoryHash, nextRetrieveType, GCMprefs, updateJobInfoPref, regid);
                testresync3(aJobsCategoryHash, nextRetrieveType, GCMprefs, updateJobInfoPref, regid);
            } else if (nextRetrieveType == -1) {
                //finished resync all 6 categories
                //do a second check if theres still que for updating job status
                objGlobalMethods.writeToFile("JobsHandler RegetSpecificJobCategoryCount03SQLite calling endOfResync when nextRetrieveType = " + String.valueOf(nextRetrieveType), "", "", "", "");
                //endOfResync(GCMprefs, updateJobInfoPref);
                endOfResync3(GCMprefs, updateJobInfoPref);
            }
        }
    }

    public static void endOfResync3(SharedPreferences GcmPreferences, SharedPreferences updateJobInfoPref) {
        String username;
        String pwd;
        String useridx;
        String ishomesuser;
        String[] UsernamePwd = new String[4];
        String regid = "";
        int queCount = 0;

        try {
            UsernamePwd = objGlobalMethods.getLoginUsernamePwd(GcmPreferences);
            username = UsernamePwd[0];
            pwd = UsernamePwd[1];
            useridx = UsernamePwd[2];
            ishomesuser = UsernamePwd[3];
            regid = objGlobalMethods.getRegistrationIdOnly();
            if (!Boolean.parseBoolean(ishomesuser)) {
                //doubleCheckUpdatePIPSQLite(GcmPreferences, updateJobInfoPref, regid, username, useridx, true);
                doubleCheckUpdatePIPSQLiteNew(GcmPreferences, updateJobInfoPref, regid, username, useridx);
            }

            queCount = returnNumberOfQueToSend(updateJobInfoPref);

            dbObjTradeInList[] TradeInList = null;
            int TradeInModelCount = 0;
            TradeInModelCount = DAO_Jobs.getModelListCount();
            if (TradeInModelCount == 0) {
                TradeInList = WebService.GetTradeInList(regid);
                if (TradeInList != null && TradeInList.length > 0) {
                    DAO_Jobs.insertTradeInList(TradeInList);
                }
            }

            if (queCount > 0) {
                backEndIsRunning = true;
                FCMservice.enablePush = false;
                objGlobalMethods.writeToFile("Backend continue, " + queCount + " queues still exist.",
                        "", "", username, useridx);
                processUpdateJobInfoStatusQue2(GcmPreferences, updateJobInfoPref);
            } else if (queCount == 0) {
                backEndIsRunning = false;
                //updateCallRaised = false;
                FCMservice.enablePush = true;

                /*if (actionCount != null && actionCount > 0) {
                    setCurrDTasPrevDTforIdlingCheck();
                }*/

                String forceLogOutBooleanString;
                forceLogOutBooleanString = objGlobalMethods.getGCMPrefs(GcmPreferences, "forceLogOutBooleanString");
                if (!forceLogOutBooleanString.equals("") && forceLogOutBooleanString.equals("true")) {
                    checkForAttachmentToEmailOut3(username, pwd);
                    storeLogin(GcmPreferences, "", "", "", "false");
                }
            }
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception caught at JobsHandler endOfResync3. Exception: " + e.toString(), "", "", "", "");
            backEndIsRunning = false;

            setCurrDTasPrevDTforIdlingCheck();
            startBackendRun15SecCounter();
        }
    }

    public static void checkForAttachmentToEmailOut3(final String username, final String pwd) {
        Date dt = new Date();
        String attachmentfilename = "";
        try {
            String versionname = objGlobalMethods.getAppVersionName(myApp.getAppContext());
            String zippedFilePath = "";
            //zippedFilePath = objGlobalMethods.getZippedLogFilesAbsolutePath();
            if (!zippedFilePath.isEmpty() && !zippedFilePath.equals("") && zippedFilePath != "") {
                String subj = "Luke report from " + username + ". Version " + versionname;
                objGlobalMethods.prepareSendEmail(new String[]{"it@xdel.com"}, subj,
                        "Luke report from handheld.", zippedFilePath, true, subj);
            } else {
                try {
                    SimpleDateFormat formatter = new SimpleDateFormat("ddMMyyyy");
                    String Filenamedtstr = "";
                    Filenamedtstr = formatter.format(dt);
                    File externalStorageDir = Environment.getExternalStorageDirectory();
                    attachment = new File(externalStorageDir, Filenamedtstr + "_log.txt");
                } catch (Exception e) {
                    attachment = null;
                }

                if (attachment.exists()) {
                    attachmentfilename = attachment.getAbsolutePath().toString();
                    if (!attachmentfilename.equals("")) {

                        Mail m = new Mail("luke@xdel.com", "XDel2015");
                        objGlobalMethods.sendEmail3(m, attachmentfilename, "Luke report from " + username + ", Version: " + versionname, "", attachment);
                    }
                }
            }
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception caught at JobsHandler voidcheckForAttachmentToEmailOut3. Exception: " + e.toString(), "", "", "", "");
        } finally {
            LogOutWSCall3(username, pwd);
        }
    }

