    public static int allSelectedAttemptedEarlierOrNot(int cattype, objCheckedItems[] objCheckedItemsAL) {
        //flag value
        //0 == no job earlier or later
        //1 == has job earlier or later
        //2 == has job not earlier or later
        //if has both 1 & 2, not all jobs earlier or later

        int flag = 0;
        Boolean asd = true;
        objJobInfo ji = null;
        objCheckedItems objCheckedItemsobj = null;
        try {
            if (objCheckedItemsAL != null && objCheckedItemsAL.length > 0) {
                for (int i = 0; i <= objCheckedItemsAL.length - 1; i++) {
                    objCheckedItemsobj = objCheckedItemsAL[i];
                    ji = objCheckedItemsobj.jobinfo;
                    if (JobsHandler.attemptTimeIsEarlierOrLaterThanWindow(cattype, ji)) {
                        if ((flag & 1) != 1) {
                            flag += 1;
                        }
                    } else {
                        if ((flag & 2) != 2) {
                            flag += 2;
                        }
                    }
                    if ((((flag & 1) == 1) && ((flag & 2) == 2)) || ((flag & 2) == 2)) {
                        flag = 0;
                        break;
                    }
                }
            }
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception at JobsHandler allSelectedAttemptedEarlierOrNot. Exception: " + e.getMessage(), "", "", "", "");
            asd = false;
        } finally {
            return flag;
        }
    }

