    public static List<Integer> IsXdelCashOrCustCash(objJobInfo ji, int catType) {
        List<Integer> iAL = new ArrayList<>();
        Boolean asd = false;
        //-1 == error
        //0 == Xdel Cash
        //1 == Cust Cash
        try {
            if (catType == 0 || catType == 1) {
                if (ji.COD > 0.0 && (ji.CODCollectAt != null && ji.CODCollectAt == 0) && (ji.CODCollected == null || !ji.CODCollected)) {
                    iAL.add(0);
                }
            } else if (catType == 2 || catType == 3) {
                if (ji.COD > 0.0 && (ji.CODCollectAt != null && ji.CODCollectAt == 1) && (ji.CODCollected == null || !ji.CODCollected)) {
                    iAL.add(0);
                    asd = true;
                }

                if ((ji.DOList != null && ji.DOList.length > 0)) {
                    for (int i = 0; i <= ji.DOList.length - 1; i++) {
                        if (ji.DOList[i].Amount > 0.0 && (ji.DOList[i].CODList == null || ji.DOList[i].CODList.length == 0)) {
                            iAL.add(1);
                            asd = true;
                            break;
                        }
                    }
                }

                if (!asd) {
                    objJobInfo linkedjob = null;
                    if (ji.LinkedJobs != null && ji.LinkedJobs.length > 0) {
                        linkedjob = ji.LinkedJobs[0];
                        if (linkedjob.CODCollectAt != null && linkedjob.CODCollectAt == 0 && linkedjob.COD > 0.0 && (linkedjob.CODCollected == null || !linkedjob.CODCollected)) {
                            iAL.add(0);
                        }

                    }
                }
            }
        } catch (Exception e) {
            iAL = null;
        } finally {
            return iAL;
        }
    }

    public static Boolean checkMassUpdateHasCODtoCollectOrNot(objCheckedItems[] objCheckedItemsAL, int catType, SharedPreferences gcmp) {
        Boolean asd = false;
        objJobInfo ji = null;
        objCheckedItems objCheckedItemsobj = null;
        Gson gson = new Gson();
        try {
            if (objCheckedItemsAL != null && objCheckedItemsAL.length > 0) {
                outer:
                for (int i = objCheckedItemsAL.length - 1; i >= 0; i--) {
                    ji = null;
                    objCheckedItemsobj = null;
                    objCheckedItemsobj = objCheckedItemsAL[i];
                    ji = gson.fromJson(objCheckedItemsobj.JobInfoJsonStr, objJobInfo.class);

                    if (catType == 0) {
                        //check for XDel's COD only since PIP,PU only consists of XDel's COD, nothing to do with cust COD
                        if (ji.CODCollectAt != null && ji.CODCollectAt == 0 && ji.COD > 0.0 && (ji.CODCollected == null || !ji.CODCollected)) {
                            asd = true;
                            return asd;
                        }
                    } else if (catType == 2) {
                        if (ji.CODCollectAt != null && ji.CODCollectAt == 1 && ji.COD > 0.0 && (ji.CODCollected == null || !ji.CODCollected)) {
                            asd = true;
                            return asd;
                        }

                        if (ji.COD == 0.0 || (ji.DOList != null && ji.DOList.length > 0)) {
                            //check for cust COD ie DO INV
                            for (int x = 0; x <= ji.DOList.length - 1; x++) {
                                if (ji.DOList[x].Amount > 0.0 && (ji.DOList[x].CODList == null || ji.DOList[x].CODList.length == 0)) {
                                    asd = true;
                                    return asd;
                                }
                            }
                        }

                        //check if got part #2 n if got, check for XDel cash collection @ pip location
                        if (!asd) {
                            objJobInfo linkedjob = null;
                            if (ji.LinkedJobs != null && ji.LinkedJobs.length > 0) {
                                linkedjob = ji.LinkedJobs[0];
                                if (linkedjob.CODCollectAt != null && linkedjob.CODCollectAt == 0 && linkedjob.COD > 0.0 && (linkedjob.CODCollected != null || !linkedjob.CODCollected)) {
                                    objGlobalMethods.setGCMPrefs(gcmp, "part2puHasCOD", "true");
                                    asd = true;
                                    return asd;
                                }
                            }
                        }
                    }
                }
            } else {
                asd = false;
            }
        } catch (Exception e) {
            asd = false;
        } finally {
            return asd;
        }
    }

