    public static void processCODJobs() {
        //R6: no COD refresh while RootGuard blocks this process, so the stored COD list and total are not cleared
        if (RootGuard.blockOperation("JobsHandler.processCODJobs", null)) {
            return;
        }
        Date dt = new Date();
        SharedPreferences GcmPreferences = objGlobalMethods.getGcmPreferences();
        String regid = objGlobalMethods.getRegistrationId(null, GcmPreferences);
        List<objCODjobInfo> freshobjCODjobInfoList = null;
        List<objCODjobInfo> freshEXTRAobjCODjobInfoList = null;
        objCODjobInfo[] freshobjCODjobInfoAL = null;
        objCODjobInfo[] objCODjobInfoALnew = null;

        objCODjobInfo oldCODjobInfo;
        objCODjobInfo newCODjobInfo;
        Gson gson = new Gson();
        String JsonStr;
        ArrayList<objCODjobInfo> currCODJobInfoAR;
        Boolean exist = false;
        ArrayList<Long> currCODJobInfoIDXsAL;
        ArrayList<Long> freshCODJobInfoIDXsAL = new ArrayList<>();
        ArrayList<Long> freshEXTRACODJobInfoIDXsAL = new ArrayList<>();

        long[] currCODJobsIDXAL;
        long[] freshCODJobsIDXAL;
        long[] freshEXTRACODJobsIDXAL;

        objJobInfo[] ALfreshExtraCODJobInfoAL;

        try {
            //get curr COD Jobs list from device
            JsonStr = objGlobalMethods.getGCMPrefs(GcmPreferences, "custXDelTotalCashPrefStr");
            if (!JsonStr.equals("")) {
                currCODJobInfoAR = gson.fromJson(JsonStr, new TypeToken<List<objCODjobInfo>>() {
                }.getType());
            } else {
                currCODJobInfoAR = new ArrayList<>();
            }

            //get fresh COD Jobs List from server
            freshobjCODjobInfoAL = WebService.getCODjobInfoAL(regid);
            if (freshobjCODjobInfoAL != null && freshobjCODjobInfoAL.length > 0) {
                freshobjCODjobInfoList = new ArrayList<objCODjobInfo>(Arrays.asList(freshobjCODjobInfoAL));

                //prepare JobsIDX arraylist for those new COD Jobs, the arraylist is used to grab array of jobInfo via webservice
                for (int i = 0; i <= freshobjCODjobInfoList.size() - 1; i++) {
                    if (!freshCODJobInfoIDXsAL.contains(freshobjCODjobInfoList.get(i).JobsIDX)) {
                        freshCODJobInfoIDXsAL.add(freshobjCODjobInfoList.get(i).JobsIDX);
                    }
                }

                if (currCODJobInfoAR != null && currCODJobInfoAR.size() > 0) {
                    //remove any COD jobs from currCODJobInfoAR not inside freshobjCODjobInfoAL
                    for (int i = currCODJobInfoAR.size() - 1; i >= 0; i--) {
                        if (!freshCODJobInfoIDXsAL.contains(currCODJobInfoAR.get(i).JobsIDX)) {
                            currCODJobInfoAR.remove(i);
                        }
                    }

                    if (currCODJobInfoAR != null && currCODJobInfoAR.size() > 0) {
                        currCODJobInfoIDXsAL = new ArrayList<>();
                        for (int i = 0; i <= currCODJobInfoAR.size() - 1; i++) {
                            currCODJobInfoIDXsAL.add(currCODJobInfoAR.get(i).JobsIDX);
                        }

                        if (currCODJobInfoIDXsAL != null && currCODJobInfoIDXsAL.size() > 0) {
                            //filter out those new Extra JobsInfo n add into current
                            for (int i = 0; i <= freshCODJobInfoIDXsAL.size() - 1; i++) {
                                if (!currCODJobInfoIDXsAL.contains(freshCODJobInfoIDXsAL.get(i))) {
                                    freshEXTRACODJobInfoIDXsAL.add(freshCODJobInfoIDXsAL.get(i));
                                    if (freshEXTRAobjCODjobInfoList == null) {
                                        freshEXTRAobjCODjobInfoList = new ArrayList<>();
                                    }
                                    for (int x = 0; x <= freshobjCODjobInfoList.size() - 1; x++) {
                                        if (freshobjCODjobInfoList.get(x).JobsIDX.equals(freshCODJobInfoIDXsAL.get(i))) {
                                            freshEXTRAobjCODjobInfoList.add(freshobjCODjobInfoList.get(x));
                                        }
                                    }
                                }
                            }

                            processCODjobsUsingEXTRACODJobInfoIDXsAL(currCODJobInfoAR, freshEXTRAobjCODjobInfoList, freshEXTRACODJobInfoIDXsAL, freshobjCODjobInfoList, freshCODJobInfoIDXsAL, GcmPreferences);

                        } else if (currCODJobInfoIDXsAL == null || currCODJobInfoIDXsAL.size() == 0) {
                            //take everything from fresh, no filter
                            processCODjobsUsingfreshCODJobInfoIDXsALOnly(freshobjCODjobInfoList, freshCODJobInfoIDXsAL, GcmPreferences);
                        }
                    } else if (currCODJobInfoAR == null || currCODJobInfoAR.size() == 0) {
                        processCODjobsUsingfreshCODJobInfoIDXsALOnly(freshobjCODjobInfoList, freshCODJobInfoIDXsAL, GcmPreferences);
                    }
                } else {
                    //curr COD Jobs list from device is empty
                    //add all jobs from freshobjCODjobInfoList into device

                    processCODjobsUsingfreshCODJobInfoIDXsALOnly(freshobjCODjobInfoList, freshCODJobInfoIDXsAL, GcmPreferences);
                }
            } else {
                if (freshobjCODjobInfoAL == null) {
                    /*objGlobalMethods.setGCMPrefs(GcmPreferences, "regetCOD", "true");*/
                }
                //error or fresh COD Jobs List is empty, set device COD Jobs to empty
                objGlobalMethods.setGCMPrefs(GcmPreferences, "totalCOD", "0.0");
                objGlobalMethods.setGCMPrefs(GcmPreferences, "custXDelTotalCashPrefStr", "");
            }

            if (currentActivity != null && currentActivity.getClass() == DrawerMainActivity.class) {
                final DrawerMainActivity act = (DrawerMainActivity) currentActivity;
                act.runOnUiThread(new Runnable() {
                    public void run() {
                        // Notifiy activity
                        //act.updateDrawerCOD();
                        act.updateDrawerCODNew(null);
                    }
                });
            } else if (currentActivity != null && currentActivity.getClass() == DrawerMain2Activity.class) {
                final DrawerMain2Activity act = (DrawerMain2Activity) currentActivity;
                act.runOnUiThread(new Runnable() {
                    public void run() {
                        // Notifiy activity
                        //act.updateDrawerCOD();
                        act.updateDrawerCODNew(null);
                    }
                });
            }

        } catch (Exception e) {
            /*objGlobalMethods.setGCMPrefs(GcmPreferences, "regetCOD", "true");*/
            objGlobalMethods.writeToFile("Exception caught at JobsHandler processCODJobs. Exception: " + e.toString(), "", "", "", "");
        }
    }

    private static void processCODjobsUsingEXTRACODJobInfoIDXsAL(ArrayList<objCODjobInfo> currCODJobInfoAR, List<objCODjobInfo> freshEXTRAobjCODjobInfoList,
                                                                 ArrayList<Long> freshEXTRACODJobInfoIDXsAL, List<objCODjobInfo> freshobjCODjobInfoList,
                                                                 ArrayList<Long> freshCODJobInfoIDXsAL, SharedPreferences GcmPreferences) {
        Date dt = new Date();
        Long[] freshEXTRACODJobsIDXAL;
        objCODjobInfo newCODjobInfo;
        Gson gson = new Gson();
        String JsonStr = "";
        String regid = GcmPreferences.getString(objGlobalVariables.PROPERTY_REG_ID, "");
        objJobInfo[] ALfreshExtraCODJobInfoAL;
        Double totalCOD = 0.0;

        try {
            if (freshEXTRACODJobInfoIDXsAL != null && freshEXTRACODJobInfoIDXsAL.size() > 0 && freshEXTRAobjCODjobInfoList != null && freshEXTRAobjCODjobInfoList.size() > 0) {
                freshEXTRACODJobsIDXAL = new Long[freshEXTRACODJobInfoIDXsAL.size()];
                for (int i = 0; i <= freshEXTRACODJobInfoIDXsAL.size() - 1; i++) {
                    freshEXTRACODJobsIDXAL[i] = freshEXTRACODJobInfoIDXsAL.get(i);
                }

                ALfreshExtraCODJobInfoAL = WebService.GetDriverJobsInfoAL(regid, freshEXTRACODJobsIDXAL, "L2_GetDriverJobInfo");

                if (ALfreshExtraCODJobInfoAL != null && ALfreshExtraCODJobInfoAL.length > 0) {
                    for (int i = 0; i <= freshEXTRAobjCODjobInfoList.size() - 1; i++) {
                        newCODjobInfo = freshEXTRAobjCODjobInfoList.get(i);
                        for (int x = 0; x <= ALfreshExtraCODJobInfoAL.length - 1; x++) {
                            if (ALfreshExtraCODJobInfoAL[x].JobsIDX == newCODjobInfo.JobsIDX) {
                                newCODjobInfo.JobInfo = ALfreshExtraCODJobInfoAL[x];
                                newCODjobInfo.ConsignmentNote = ALfreshExtraCODJobInfoAL[x].ConsignmentNote;
                                if (newCODjobInfo.ConsignmentNote.equals("")) {
                                    newCODjobInfo.ConsignmentNote = ALfreshExtraCODJobInfoAL[x].JobNo;
                                }

                                if (newCODjobInfo.InvoiceIDX > 0) {
                                    if (ALfreshExtraCODJobInfoAL[x].DOList != null && ALfreshExtraCODJobInfoAL[x].DOList.length > 0) {
                                        for (int inv = 0; inv <= ALfreshExtraCODJobInfoAL[x].DOList.length - 1; inv++) {
                                            if (newCODjobInfo.InvoiceIDX == ALfreshExtraCODJobInfoAL[x].DOList[inv].DOIDX) {
                                                newCODjobInfo.DOInvoice = ALfreshExtraCODJobInfoAL[x].DOList[inv].Invoice;
                                                newCODjobInfo.CODcollectionAtCatType = 2;
                                                break;
                                            }
                                        }
                                    }
                                } else {
                                    newCODjobInfo.DOInvoice = "";
                                    if (ALfreshExtraCODJobInfoAL[x].CODCollectAt == 0) {
                                        newCODjobInfo.CODcollectionAtCatType = 0;
                                    } else if (ALfreshExtraCODJobInfoAL[x].CODCollectAt == 1) {
                                        newCODjobInfo.CODcollectionAtCatType = 2;
                                    }

                                }

                                if (newCODjobInfo.CollectionStatus == -1) {
                                    newCODjobInfo.imgmaincodStatusImgSrc = -1;
                                } else if (newCODjobInfo.CollectionStatus == 0) {
                                    newCODjobInfo.imgmaincodStatusImgSrc = 0;
                                } else if (newCODjobInfo.CollectionStatus == 1) {
                                    newCODjobInfo.imgmaincodStatusImgSrc = 1;
                                } else if (newCODjobInfo.CollectionStatus == 2) {
                                    newCODjobInfo.imgmaincodStatusImgSrc = 2;
                                } else if (newCODjobInfo.CollectionStatus == 3) {
                                    newCODjobInfo.imgmaincodStatusImgSrc = 3;
                                }

                                if (ALfreshExtraCODJobInfoAL[x].StatusCodeIDX == 103) {
                                    newCODjobInfo.categoryTitle = myApp.getAppContext().getString(R.string.item_dashboard2PIP);
                                    newCODjobInfo.catType = 0;

                                } else if (ALfreshExtraCODJobInfoAL[x].StatusCodeIDX == 49) {
                                    newCODjobInfo.categoryTitle = myApp.getAppContext().getString(R.string.item_dashboard2PU);
                                    newCODjobInfo.catType = 1;

                                } else if (ALfreshExtraCODJobInfoAL[x].StatusCodeIDX == 104) {
                                    newCODjobInfo.categoryTitle = myApp.getAppContext().getString(R.string.item_dashboard2DIP);
                                    newCODjobInfo.catType = 2;

                                } else if (ALfreshExtraCODJobInfoAL[x].StatusCodeIDX == 135) {
                                    newCODjobInfo.categoryTitle = myApp.getAppContext().getString(R.string.item_dashboard2OKP);
                                    newCODjobInfo.catType = 3;
                                }

                                currCODJobInfoAR.add(newCODjobInfo);
                            }
                        }
                    }
                }

                //save
                if (currCODJobInfoAR != null && currCODJobInfoAR.size() > 0) {
                    JsonStr = gson.toJson(currCODJobInfoAR);

                    for (int i = 0; i <= currCODJobInfoAR.size() - 1; i++) {
                        totalCOD += currCODJobInfoAR.get(i).Amount;
                    }

                    if (totalCOD == 0.0) {
                        objGlobalMethods.setGCMPrefs(GcmPreferences, "totalCOD", "0.0");
                    } else if (totalCOD > 0.0) {
                        objGlobalMethods.setGCMPrefs(GcmPreferences, "totalCOD", String.valueOf(totalCOD));
                    }

                    if (!JsonStr.equals("") && !JsonStr.equals("[]")) {
                        objGlobalMethods.setGCMPrefs(GcmPreferences, "custXDelTotalCashPrefStr", JsonStr);
                    } else if (JsonStr.equals("") || JsonStr.equals("[]")) {
                        objGlobalMethods.setGCMPrefs(GcmPreferences, "custXDelTotalCashPrefStr", "");
                    }

                } else if (currCODJobInfoAR == null || currCODJobInfoAR.size() == 0) {
                    objGlobalMethods.setGCMPrefs(GcmPreferences, "totalCOD", "0.0");
                    objGlobalMethods.setGCMPrefs(GcmPreferences, "custXDelTotalCashPrefStr", "");
                }

                if (ALfreshExtraCODJobInfoAL == null) {
                    /*objGlobalMethods.setGCMPrefs(GcmPreferences, "regetCOD", "true");*/
                }
            } else if (freshEXTRACODJobInfoIDXsAL == null || freshEXTRACODJobInfoIDXsAL.size() == 0) {
                processCODjobsUsingfreshCODJobInfoIDXsALOnly(freshobjCODjobInfoList, freshCODJobInfoIDXsAL, GcmPreferences);
            }
        } catch (Exception e) {
            /*objGlobalMethods.setGCMPrefs(GcmPreferences, "regetCOD", "true");*/
            objGlobalMethods.writeToFile("Exception caught at JobsHandler processCODjobsUsingEXTRACODJobInfoIDXsAL. Exception: " + e.toString(), "", "", "", "");
            /*objGlobalMethods.setGCMPrefs(GcmPreferences, "totalCOD", "0.0");
            objGlobalMethods.setGCMPrefs(GcmPreferences, "custXDelTotalCashPrefStr", "");*/
        }
    }

