    public static boolean hasSameChecklist(String[] c1, String[] c2, String[] c3, String[] c4) {
        boolean asd = false;
        String str1 = "";
        String str2 = "";
        try {
            if (c4 != null && c4.length > 0) {
                if (c3 != null) {
                    asd = SameChecklist(c3, c4);
                } else if (c2 != null) {
                    asd = SameChecklist(c2, c4);
                } else if (c1 != null) {
                    asd = SameChecklist(c1, c4);
                }
            }
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception caught at JobsHandler hasSameChecklist. Exception: " + e.getMessage().toString(), "", "", "", "");
        } finally {
            return asd;
        }
    }

    private static boolean SameChecklist(String[] c1, String[] c2) {
        boolean asd = true;
        String str1 = "";
        String str2 = "";
        try {
            if (c1 != null && c2 != null && c1.length == c2.length) {
                for (int i = 0; i <= c1.length - 1; i++) {
                    str1 = c1[i];
                    str2 = c2[i];
                    if (str1.contains(".ID.")) {
                        str1 = str1.substring(0, 11);
                    }
                    if (str2.contains(".ID.")) {
                        str2 = str2.substring(0, 11);
                    }
                    if (!objGlobalMethods.IsEqualString(str1, str2)) {
                        asd = false;
                        break;
                    }
                }
            } else {
                asd = false;
            }
        } catch (Exception e) {
            asd = false;
            objGlobalMethods.writeToFile("Exception at JobsHandler SameChecklist. Exception: " + e.getMessage(), "", "", "", "");
        } finally {
            return asd;
        }
    }

    public static Boolean HasCheckList(String[] checklist, String ActionCode) {
        ////PS PickSuccess
        ////PF PickFail
        ////DS DeliverySuccess
        ////DF DeliverFail
        ////CS CollectionSuccess
        ////CF CollectionFail
        ////RS ReturnSuccess
        ////RF ReturnFail
        Boolean asd = false;
        String FullCode = "";
        String[] codesArr = null;
        String ActionCode_A = "";
        int index = 0;
        try {
            if (checklist != null && checklist.length > 0) {
                for (int i = 0; i <= checklist.length - 1; i++) {
                    index = checklist[i].indexOf("|");
                    if (index >= 0) {
                        FullCode = checklist[i].substring(0, index);
                        if (FullCode != "") {
                            codesArr = FullCode.split("\\.");
                            ActionCode_A = codesArr[1];
                            if (ActionCode_A.equals(ActionCode)) {
                                asd = true;
                                break;
                            }
                        }
                    }
                }
            }
        } catch (Exception e) {
            String s = getStackTraceString(e);
            objGlobalMethods.writeToFile("Exception caught at JobsHandler HasCheckList. Exception: " + e.getMessage() + "\nStack: " + s, "", "", "", "");
            asd = false;
        } finally {
            return asd;
        }
    }

