    public static boolean hasImgFileMoreThan7MinOld(ArrayList<String> imagePaths, ArrayList<CustomGallery> dataT, CustomGallery dat) {
        boolean asd = false;
        int NoOfItemProofImg = 0;
        try {
            if (dat != null && dat.isItemProof && !objGlobalMethods.IsEmptyString(dat.sdcardPath)) {
                NoOfItemProofImg++;
                if (fileIsMoreThan7MinOld(dat.sdcardPath)) {
                    asd = true;
                }
            }

            if (!asd) {
                if (imagePaths != null && imagePaths.size() > 0 && dataT != null && dataT.size() > 0) {
                    for (int i = 0; i <= dataT.size() - 1; i++) {
                        if (dataT.get(i).isItemProof) {
                            NoOfItemProofImg++;
                            if (fileIsMoreThan7MinOld(imagePaths.get(i))) {
                                asd = true;
                                break;
                            }
                        }
                    }
                    if (!asd && NoOfItemProofImg == 0) {
                        asd = true;
                    }
                } else if (NoOfItemProofImg == 0) {
                    asd = true;
                }
            }
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception at JobsHandler hasImgFileMoreThan7MinOld. Exception: " + e.getMessage(), "", "", "", "");
            asd = false;
        } finally {
            return asd;
        }
    }

