    public static Boolean attemptTimeIsEarlierOrLaterThanWindow(int cattype, objJobInfo ji) {
        boolean asd = false;
        boolean isTodayDelivery = false;
        Date[] DatesAL;
        Date rdyDateTime = null;
        Date pubyDateTime = null;
        Date fromDateTime = null;
        Date toDateTime = null;
        Date extDateTime = null;
        Date now = new Date();
        /*Calendar calendartweakedDateTo = new GregorianCalendar(2020, 4, 12, 11, 30, 0);
        now = calendartweakedDateTo.getTime();*/
        Date ZeroTimeDateNow = objGlobalMethods.getZeroTimeDate(now);
        Date ZeroSecondsNow = objGlobalMethods.getZeroSecondsTimeDate(now);
        boolean fromIsToday = false;
        boolean toIsToday = false;
        boolean extIsToday = false;
        boolean isBetweenDates = false;
        boolean isEarlierThanFromDT = false;
        boolean isLaterThanToDT = false;
        boolean FromDTisLaterThanToday = false;
        //0 comes when two date are same,
        //1 comes when date1 is higher then date2
        //-1 comes when date1 is lower then date2

        try {
            if (ji != null) {
                DatesAL = objGlobalMethods.returnAllDates(ji);
                if (cattype == 0) {
                    rdyDateTime = DatesAL[2];
                    pubyDateTime = DatesAL[1];
                } else if (cattype == 2) {
                    fromDateTime = DatesAL[0] == null ? null : objGlobalMethods.getZeroSecondsTimeDate(DatesAL[0]);
                    toDateTime = DatesAL[3] == null ? null : objGlobalMethods.getZeroSecondsTimeDate(DatesAL[3]);
                    extDateTime = DatesAL[4] == null ? null : objGlobalMethods.getZeroSecondsTimeDate(DatesAL[4]);

                    if (fromDateTime != null) {
                        Calendar fromDateTimeC = Calendar.getInstance();
                        fromDateTimeC.setTime(fromDateTime);
                        fromDateTimeC.add(Calendar.MINUTE, -15);
                        fromDateTime = fromDateTimeC.getTime();
                        fromIsToday = objGlobalMethods.getZeroTimeDate(fromDateTime).compareTo(ZeroTimeDateNow) == 0;
                        FromDTisLaterThanToday = objGlobalMethods.getZeroTimeDate(fromDateTime).compareTo(ZeroTimeDateNow) == 1;
                        isEarlierThanFromDT = fromDateTime.compareTo(ZeroSecondsNow) == 1;
                    }

                    if (toDateTime != null) {
                        Calendar toDateTimeC = Calendar.getInstance();
                        toDateTimeC.setTime(toDateTime);
                        toDateTimeC.add(Calendar.MINUTE, 15);
                        toDateTime = toDateTimeC.getTime();
                        toIsToday = objGlobalMethods.getZeroTimeDate(toDateTime).compareTo(ZeroTimeDateNow) == 0;
                        isLaterThanToDT = ZeroSecondsNow.compareTo(toDateTime) == 1;
                    }

                    if (extDateTime != null) {
                        Calendar extDateTimeC = Calendar.getInstance();
                        extDateTimeC.setTime(extDateTime);
                        extDateTimeC.add(Calendar.MINUTE, 15);
                        extDateTime = extDateTimeC.getTime();
                        extIsToday = objGlobalMethods.getZeroTimeDate(extDateTime).compareTo(ZeroTimeDateNow) == 0;
                    }

                    if ((fromDateTime == null || toDateTime == null) || (fromDateTime == null && toDateTime == null)) {
                        asd = false;
                    } else if (fromDateTime != null && toDateTime != null) {
                        if (FromDTisLaterThanToday || (fromIsToday && isEarlierThanFromDT)) {
                            //del fromDate is later than today or fromDate is today and now is earlier than fromDatetime
                            asd = true;
                        }
                    }
                }
            }
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception at JobsHandler attemptTimeIsEarlierOrLaterThanWindow. Exception: " + e.getMessage(), "", "", "", "");
            asd = false;
        } finally {
            return asd;
        }
    }

