    public static String[] getIMEIorSerialorVoucherBreakdownString(int type, String v) {
        //type 1 == imei 2 == serial number 3 == voucher
        String[] res = new String[2];
        String ss1 = "";
        String ss2 = "";
        try {
            if (type == 1 && v.length() >= 7) {
                int startindex = v.length() - 7;
                ss1 = v.substring(0, startindex);
                ss2 = v.substring(startindex);
            } else if (type == 1 && v.length() < 7) {
                ss1 = "";
                ss2 = v;
            } else if (type == 2 && v.length() >= 4) {
                int startindex = v.length() - 4;
                ss1 = v.substring(0, startindex);
                ss2 = v.substring(startindex);
            } else if (type == 2 && v.length() < 4) {
                ss1 = "";
                ss2 = v;
            } else if (type == 3 && v.length() >= 4) {
                int startindex = v.length() - 4;
                ss1 = v.substring(0, startindex);
                ss2 = v.substring(startindex);
            } else if (type == 3 && v.length() < 4) {
                ss1 = "";
                ss2 = v;
            }

            res[0] = ss1;
            res[1] = ss2;
        } catch (Exception e) {
            String s = getStackTraceString(e);
            objGlobalMethods.writeToFile("Exception at JobsHandler getIMEIorSerialorVoucherBreakdownString. Exception: " + e.getMessage() + "\nStack: " + s, "", "", "", "");
        } finally {
            return res;
        }
    }

