    public static Boolean PromptDistanceViolationUponUpdate(objJobInfo ji, int catType, int submissionAction) {
        Boolean asd = false;
        int tolerance = 0;
        try {
            Location DestinationLocationFD = objGlobalMethods.getDestinationLocation(ji, catType);
            Location gpsLocationFD = objGlobalMethods.getLastKnownLocationForJobUpdate();
            tolerance = objGlobalMethods.getDestinationTolerance(ji, catType);

            if (objGlobalMethods.IsOutOfDestinationLocationRange(DestinationLocationFD, gpsLocationFD, tolerance)) {
                asd = true;
                float distMeter = gpsLocationFD.distanceTo(DestinationLocationFD);
                String action = submissionAction == 0 ? " to update FP" : submissionAction == 1 ? " to update PU" : submissionAction == 3 ? " to update FD" :
                        submissionAction == 4 ? "to update OKP" : " unknown action";
                objGlobalMethods.writeToFile("Out of range " + action + " for JobsIDX: " + ji.JobsIDX + ", Destination LatLng: "
                        + DestinationLocationFD.getLatitude() + ", " + DestinationLocationFD.getLongitude() + ", gpsLocation LatLng: "
                        + gpsLocationFD.getLatitude() + ", " + gpsLocationFD.getLongitude() + ", Distance: " + distMeter + "meters.", "", "", "", "");
            }
        } catch (Exception e) {
            String stack = getStackTraceString(e);
            asd = false;
        } finally {
            return asd;
        }
    }

