    public static Boolean validSecurityBagSealNumber(String val) {
        Boolean asd = false;
        try {
            if (val != null && val.length() > 0) {
                if (val.matches("\\d+(?:\\.\\d+)?") && val.length() == 6) {
                    asd = true;
                } else if (val.length() == 8) {
                    String val1 = val.substring(0, 1).toLowerCase();
                    String val2 = val.substring(1, 2);
                    String val3 = val.substring(2);
                    asd = (val1.equals("z") && Pattern.matches("[a-zA-Z]+", val2) && val3.matches("\\d+(?:\\.\\d+)?") && !val1.equals(val2));
                }
            }
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception at JobsHandler validSecurityBagSealNumber. Exception: " + e.getMessage().toString(), "", "", "", "");
            asd = false;
        } finally {
            return asd;
        }
    }

