    public static String returnListOfDOINV(String JobsIDX) {

        ArrayList<objDOObject> al = null;
        Context ctx = myApp.getAppContext();
        String header = ctx.getString(R.string.alert_checkfordo);
        String doinv = "";
        String raw = "";
        String[] splitted;

        try {
            if (!JobsIDX.isEmpty() && !JobsIDX.equals("") && JobsIDX != "" && !JobsIDX.equals("[]") && JobsIDX != "[]") {
                al = DAO_Jobs.getDOINV_ListViaJobsIDXs(JobsIDX);
            }

            if (al != null && al.size() > 0) {
                for (int i = 0; i <= al.size() - 1; i++) {
                    splitted = null;
                    raw = al.get(i).Invoice;
                    if (!raw.isEmpty() && !raw.equals("") && raw != "" && !raw.equals("\\[\\]") && raw != "\\[\\]") {
                        //remove first [
                        raw = raw.substring(1, raw.length());
                        //remove last ]
                        raw = raw.substring(0, raw.length() - 1);
                        splitted = raw.split("\\]\\[");
                        if (splitted != null && splitted.length > 0) {
                            for (int x = 0; x <= splitted.length - 1; x++) {
                                doinv += "\u2022" + " " + splitted[x] + "\n";
                            }
                        }
                    }
                }
                if (!doinv.isEmpty() && !doinv.equals("") && doinv != "") {
                    doinv = doinv.substring(0, doinv.length() - 1);
                    doinv = header + doinv;
                }
            }
        } catch (Exception e) {
            String s = e.getMessage().toString();
            objGlobalMethods.writeToFile("Exception at JobsHandler returnListOfDOINV. Exception: " + s, "", "", "", "");
            doinv = ctx.getString(R.string.alert_error_checkfordo);
        } finally {
            return doinv;
        }
    }

