    public static boolean QueisUpdated() {
        boolean asd = false;
        Gson gson = new Gson();
        String QCabinetDataJsonStr = "";
        String[] QCabinetData = null;
        SharedPreferences gcmp = objGlobalMethods.getGcmPreferences();
        String isUpdatedStr = "";
        boolean isUpdated = false;
        String NonProcessJobQueJsonStr = "";
        JobQueue[] res = null;
        String InitialSetOfJobsIDXsJsonStr = "";
        List<Long> InitialSetOfJobsIDXsArr = null;
        String saveAmended4QuesJsonStr = "";
        List<JobQueue> saveAmended4Ques = null;
        try {
            QCabinetDataJsonStr = objGlobalMethods.getGCMPrefs(gcmp, "QCabinetDataJsonStr");
            if (!QCabinetDataJsonStr.isEmpty() && !QCabinetDataJsonStr.equals("") && !QCabinetDataJsonStr.equals("[]")) {
                QCabinetData = gson.fromJson(QCabinetDataJsonStr, String[].class);
                if (QCabinetData != null) {
                    isUpdatedStr = QCabinetData[0];
                    if (!isUpdatedStr.isEmpty() && !isUpdatedStr.equals("") && isUpdatedStr.equals("true")) {
                        isUpdated = Boolean.parseBoolean(isUpdatedStr);
                        if (isUpdated) {
                            //saveAmended4QuesJsonStr = objGlobalMethods.getGCMPrefs(gcmp, "saveAmended4QuesJsonStr");
                            saveAmended4QuesJsonStr = objGlobalMethods.getVrpRelatedSP_KeyValue("saveAmended4QuesJsonStr");

                            InitialSetOfJobsIDXsJsonStr = QCabinetData[2];
                            if (InitialSetOfJobsIDXsJsonStr != null && !InitialSetOfJobsIDXsJsonStr.isEmpty() && !InitialSetOfJobsIDXsJsonStr.equals("") && !InitialSetOfJobsIDXsJsonStr.equals("[]")) {
                                InitialSetOfJobsIDXsArr = gson.fromJson(InitialSetOfJobsIDXsJsonStr, new TypeToken<List<Long>>() {
                                }.getType());
                            }
                            //NonProcessJobQueJsonStr = objGlobalMethods.getGCMPrefs(gcmp, "NonProcessJobQueJsonStr");
                            NonProcessJobQueJsonStr = objGlobalMethods.getVrpRelatedSP_KeyValue("NonProcessJobQueJsonStr");
                            if (!NonProcessJobQueJsonStr.equals("") || !NonProcessJobQueJsonStr.equals("[]")) {
                                res = gson.fromJson(NonProcessJobQueJsonStr, JobQueue[].class);
                            }

                            isUpdated = QueJobsIDXexistsInIntialSetOfJobsIDX(res, InitialSetOfJobsIDXsArr);
                            if (!isUpdated && !saveAmended4QuesJsonStr.isEmpty()) {
                                //objGlobalMethods.setGCMPrefs(gcmp, "saveAmended4QuesJsonStr", "");
                                objGlobalMethods.setVrpRelatedSP_KeyValue("saveAmended4QuesJsonStr", "");
                            }
                        }
                    }
                }
            }
        } catch (Exception e) {
            isUpdated = false;
            String s = getStackTraceString(e);
            objGlobalMethods.writeToFile("Exception at QueisUpdated. Exception: " + e.getMessage() + "\n" + s, "", "", "", "");
        } finally {
            return isUpdated;
        }
    }

    public static boolean JobsIDXsQueInOriginalOrder(JobQueue[] res, List<Long> InitialSetOfJobsIDXsArr) {
        boolean queInOriginalOrder = true;
        JobQueue r = null;
        int increCounter = 0;
        long initalJobsIDX = 0;
        int prevInitialIdx = -1;
        try {
            if (res != null && res.length > 0 && InitialSetOfJobsIDXsArr != null && InitialSetOfJobsIDXsArr.size() > 0) {
                boolean useInitalSize = false;
                int maxlength = 0;
                useInitalSize = (res.length == InitialSetOfJobsIDXsArr.size() || res.length > InitialSetOfJobsIDXsArr.size()) ? true : false;
                maxlength = useInitalSize ? InitialSetOfJobsIDXsArr.size() : res.length;
                outer:
                for (int i = 0; i <= maxlength - 1; i++) {
                    r = res[i];
                    if (InitialSetOfJobsIDXsArr.contains(r.JobsIDX)) {
                        for (int x = 0; x <= InitialSetOfJobsIDXsArr.size() - 1; x++) {
                            initalJobsIDX = InitialSetOfJobsIDXsArr.get(x);
                            if (r.JobsIDX == initalJobsIDX && increCounter == 0) {
                                increCounter++;
                                prevInitialIdx = x;
                                break;
                            } else if (r.JobsIDX == initalJobsIDX && increCounter > 0 && prevInitialIdx + 1 == x) {
                                increCounter++;
                                prevInitialIdx = x;
                                break;
                            } else if (r.JobsIDX == initalJobsIDX && increCounter > 0) {
                                queInOriginalOrder = false;
                                break outer;
                            }
                        }
                    } else if (increCounter == 0) {
                        //jobsidx came in later
                        continue;
                    } else if (increCounter > 0) {
                        //jobsidx came in later
                        queInOriginalOrder = false;
                        break;
                    }
                }
            }
        } catch (Exception e) {
            queInOriginalOrder = true;
        } finally {
            return queInOriginalOrder;
        }
    }

