    public static List<JobQueue> rtnEnableDisableJobQueForUpdatesNew(List<JobQueue> njq, Boolean istestuserID) {
        if (istestuserID == null)
            istestuserID = objGlobalMethods.isTestUserID();
        try {
            if (njq != null && njq.size() > 0) {
                JobQueue jq = null;
                boolean hasOpsQ = false;
                for (int i = 0; i <= njq.size() - 1; i++) {
                    jq = njq.get(i);
                    if (i == 1 && !jq.IsHeader && jq.getType().equals("ops")) {
                        hasOpsQ = true;
                        njq.get(i).setIsEnabled(true);
                    } else if ((!jq.IsHeader && jq.getType().equals("vrp") && !hasOpsQ && ((jq.Flag & 4) == 4)) && istestuserID && jq.GC_Queue == null) {
                        //weighted, non gc que, is testuserid, dun enable, for briefing purpose
                        njq.get(i).setIsEnabled(false);
                    } else if ((!jq.IsHeader && jq.getType().equals("vrp") && !hasOpsQ && ((jq.Flag & 4) == 4))) {
                        //weighted
                        njq.get(i).setIsEnabled(true);
                    } else if (!jq.IsHeader && jq.getType().equals("vrp") && (jq.isUpdated || i <= 4) && !hasOpsQ) {
                        njq.get(i).setIsEnabled(jq.isUpdated ? true : false);
                    }

                    njq.get(i).setCanClick(true);
                    njq.get(i).setID(i);
                    njq.get(i).setArrayIdx(i);
                }
            }
        } catch (Exception e) {
            String s = e.getMessage().toString();
            objGlobalMethods.writeToFile("Exception at JobsHandler rtnEnableDisableJobQueForUpdatesNew. Exception: " + s, "", "", "", "");
        } finally {
            return njq;
        }
    }

    public static List<JobQueue> rtnFinalReArrangement(List<JobQueue> njq, String nxtQlocation) {
        try {
            if (njq != null && njq.size() > 0) {
                JobQueue jq = null;
                JobQueue exjq = null;
                boolean hasOpsQ = false;
                boolean shift = false;
                int shiftidx = -1;
                boolean processshift = false;
                String prevfirstQlocation = objGlobalMethods.getGCMPrefs(objGlobalMethods.getGcmPreferences(), "prevfirstQlocation");
                if (objGlobalMethods.IsEmptyString(prevfirstQlocation)) {
                    objGlobalMethods.setGCMPrefs(objGlobalMethods.getGcmPreferences(), "prevfirstQlocation", nxtQlocation == null ? "" : nxtQlocation);
                } else if (nxtQlocation != null && !nxtQlocation.equals(prevfirstQlocation)) {
                    objGlobalMethods.setGCMPrefs(objGlobalMethods.getGcmPreferences(), "prevfirstQlocation", prevfirstQlocation);
                    processshift = true;
                }

                if (processshift && njq != null && njq.size() > 0) {
                    for (int i = 0; i <= njq.size() - 1; i++) {
                        jq = njq.get(i);
                        if (i == 1 && !jq.IsHeader && jq.getType().equals("vrp") && !jq.PostalCode.equals(prevfirstQlocation)) {
                            shift = true;
                            break;
                        }
                    }
                    if (shift) {
                        for (int i = 0; i <= njq.size() - 1; i++) {
                            jq = njq.get(i);
                            if (!jq.IsHeader && jq.getType().equals("vrp") && jq.PostalCode.equals(prevfirstQlocation)) {
                                shiftidx = i;
                                break;
                            }
                        }
                        if (shiftidx > -1) {
                            exjq = new JobQueue(njq.get(shiftidx));
                            exjq.setisUpdated(true);
                            njq.remove(shiftidx);
                            njq.add(1, exjq);
                        }
                        int c = 0;
                        for (int i = 0; i <= njq.size() - 1; i++) {
                            jq = njq.get(i);
                            if (i == 1 && !jq.IsHeader && jq.getType().equals("ops")) {
                                hasOpsQ = true;
                                njq.get(i).setIsEnabled(true);
                            } else if (!jq.IsHeader && jq.getType().equals("vrp") && (jq.isUpdated || i <= 2) && !hasOpsQ) {
                                njq.get(i).setIsEnabled(jq.isUpdated ? true : false);
                                c++;
                                if (c < 2) {
                                    njq.get(i).setisUpdated(true);
                                }
                            }
                            njq.get(i).setCanClick(true);
                            njq.get(i).setID(i);
                            njq.get(i).setArrayIdx(i);
                        }
                    }
                }
            }
        } catch (Exception e) {
            String s = e.getMessage().toString();
            objGlobalMethods.writeToFile("Exception at JobsHandler rtnFinalReArrangement. Exception: " + s, "", "", "", "");
        } finally {
            return njq;
        }
    }

