    private static boolean getIsEnabled(List<JobQueue> NewJQlist, boolean OpsHeaderExist, boolean VrpHeaderExist) {
        boolean asd = false;
        try {
            if (NewJQlist != null && NewJQlist.size() == 1 && OpsHeaderExist && !VrpHeaderExist) {
                //OpsHeaderExist exist only, for ops que
                asd = true;
            } else if (NewJQlist != null && NewJQlist.size() > 1 && OpsHeaderExist && !VrpHeaderExist) {
                //OpsHeaderExist & at least 1 ops que exist, for ops que
                asd = false;
            } else if (NewJQlist != null && NewJQlist.size() > 1 && OpsHeaderExist && VrpHeaderExist) {
                //OpsHeaderExist exist && VrpHeaderExist, for gc/vrp que
                asd = false;
            } else if (NewJQlist != null && (NewJQlist.size() == 1) && !OpsHeaderExist && VrpHeaderExist) {
                //OpsHeaderExist not exist n VrpheaderExist exist, for gc/vrp que, enable for 1st gc/vrp que
                asd = true;
            }/* else if (NewJQlist != null && (NewJQlist.size() == 1 || NewJQlist.size() == 2) && !OpsHeaderExist && VrpHeaderExist) {
                //OpsHeaderExist not exist n VrpheaderExist exist, for gc/vrp que, enable for 1st 2 gc/vrp que
                asd = true;
            }*/
        } catch (Exception e) {
            asd = true;
        } finally {
            return asd;
        }
    }

    public static JobQueue[] getAmendedJobQ(JobQueue[] req, List<dbObjJobs> al, String lastpostal, SharedPreferences gcmp, ArrayList<String> JobsPostalsToBeUNPARKED) {
        List<JobQueue> jql = new ArrayList<>();
        JobQueue[] res = req;
        dbObjJobs j = null;
        JobQueue jq = null;
        JobQueue nr = null;
        String postal = "";
        String lastJobQueueDataJsonStr = "";
        JobQueue lastjq = null;
        String mp = "";
        try {
            if (al != null && al.size() > 0 && req != null && req.length > 0) {
                lastJobQueueDataJsonStr = objGlobalMethods.getGCMPrefs(gcmp, "lastJobQueueDataJsonStr");
                lastjq = !objGlobalMethods.IsEmptyString(lastJobQueueDataJsonStr) ? new Gson().fromJson(lastJobQueueDataJsonStr, JobQueue.class) : null;
                for (int q = 0; q <= req.length - 1; q++) {
                    jq = req[q];
                    postal = jq.PostalCode;
                    jql.add(jq);

                    if (JobsPostalsToBeUNPARKED != null && JobsPostalsToBeUNPARKED.size() > 0) {
                        for (int i = JobsPostalsToBeUNPARKED.size() - 1; i >= 0; i--) {
                            mp = JobsPostalsToBeUNPARKED.get(i);
                            for (int v = al.size() - 1; v >= 0; v--) {
                                j = al.get(v);
                                if (objGlobalMethods.IsEqualString(mp, j.Postal)) {
                                    nr = new JobQueue(null, null, null, null, null, null,
                                            null, null, null, null, null, null, null, false);
                                    nr.setCUSTOM_ETA(lastjq != null ? lastjq.CUSTOM_ETA : jq.CUSTOM_ETA);
                                    nr.setCUSTOM_Queue(lastjq != null ? lastjq.CUSTOM_Queue : jq.CUSTOM_Queue);
                                    nr.setDriverIDX(lastjq != null ? lastjq.DriverIDX : jq.DriverIDX);
                                    nr.setJobsIDX(j.JobsIDX);
                                    nr.setLatitude(j.LAT);
                                    nr.setLongitude(j.LNG);
                                    nr.setPostalCode(j.Postal);
                                    nr.setVRP_ETA(lastjq != null ? lastjq.VRP_ETA : jq.VRP_ETA);
                                    nr.setVRP_Queue(lastjq != null ? lastjq.VRP_Queue : jq.VRP_Queue);
                                    nr.setIsEnabled(true);
                                    nr.setValid(true);
                                    nr.setTimeWindows(lastjq != null ? lastjq.TimeWindows : jq.TimeWindows);
                                    jql.add(nr);
                                    al.remove(v);
                                }
                            }
                            JobsPostalsToBeUNPARKED.remove(i);
                        }
                    }

                    if (!objGlobalMethods.IsEmptyString(lastpostal)) {
                        int orisize = al.size();
                        for (int i = al.size() - 1; i >= 0; i--) {
                            j = al.get(i);
                            if (objGlobalMethods.IsEqualString(lastpostal, j.Postal) && lastjq != null) {
                                nr = new JobQueue(null, null, null, null, null, null,
                                        null, null, null, null, null, null, null, false);
                                nr.setCUSTOM_ETA(lastjq.CUSTOM_ETA);
                                nr.setCUSTOM_Queue(lastjq.CUSTOM_Queue);
                                nr.setDriverIDX(lastjq.DriverIDX);
                                nr.setJobsIDX(j.JobsIDX);
                                nr.setLatitude(lastjq.Latitude);
                                nr.setLongitude(lastjq.Longitude);
                                nr.setPostalCode(lastjq.PostalCode);
                                nr.setVRP_ETA(lastjq.VRP_ETA);
                                nr.setVRP_Queue(lastjq.VRP_Queue);
                                nr.setIsEnabled(true);
                                nr.setValid(true);
                                nr.setTimeWindows(lastjq.TimeWindows);
                                al.remove(i);
                                jql.add(nr);
                            }
                        }
                    }

                    for (int i = al.size() - 1; i >= 0; i--) {
                        j = al.get(i);
                        if (objGlobalMethods.IsEqualString(postal, j.Postal)) {
                            nr = new JobQueue(null, null, null, null, null, null,
                                    null, null, null, null, null, null, null, false);
                            nr.setCUSTOM_ETA(jq.CUSTOM_ETA);
                            nr.setCUSTOM_Queue(jq.CUSTOM_Queue);
                            nr.setDriverIDX(jq.DriverIDX);
                            nr.setJobsIDX(j.JobsIDX);
                            nr.setLatitude(jq.Latitude);
                            nr.setLongitude(jq.Longitude);
                            nr.setPostalCode(postal);
                            nr.setVRP_ETA(jq.VRP_ETA);
                            nr.setVRP_Queue(jq.VRP_Queue);
                            nr.setValid(jq.Valid);
                            nr.setTimeWindows(jq.TimeWindows);
                            nr.setisLaterJob(true);
                            al.remove(i);
                            jql.add(nr);
                        }
                    }
                }
                if (jql != null && jql.size() > 0) {
                    res = jql.toArray(new JobQueue[jql.size()]);
                }
            }
        } catch (Exception e) {
            res = req;
            String s = getStackTraceString(e);
            objGlobalMethods.writeToFile("Exception at JobsHandler getJobQue2. Exception: " + e.getMessage().toString() + "\nStack: " + s, "", "", "", "");
        } finally {
            return res;
        }
    }

    public static void getJobQue2(String ARegID, boolean isRefresh, final boolean forceRefresh, final ArrayList<Integer> ListItemIndex, ArrayList<String> JobsPostalsToBeUNPARKED) {
        SharedPreferences gcmp = objGlobalMethods.getGcmPreferences();
        String JobQueJsonStr = "";
        boolean isEditingRoute = false;
        boolean hasOpsQue = false;
        JobQueue r;
        try {
            boolean IsMaintenanceHours = objGlobalMethods.currTimeIsBetweenFromDateToDateToIgnore();
            cd = new ConnectionDetector(null);
            if (cd.isConnectingToInternet()) {
                isEditingRoute = objGlobalMethods.isEditingRoute();
                JobQueue[] res = WebService.L2_GetETA(ARegID);
                int totalpipdipbal = DAO_Jobs.getTotalOutstandingNumOfPipDip();
                if (totalpipdipbal == 0) {
                    String[] prefName = new String[]{"lastpostal", "lastJobQueueDataJsonStr", "JobsPostalsToBeUNPARKEDJsonStr"};
                    String[] prefvalue = new String[]{"", "", ""};
                    objGlobalMethods.setGCMPrefsMass(gcmp, prefName, prefvalue);
                }
                if (res != null && res.length > 0) {
                    //ParkedDIP_Unparked = DAO_Jobs.updateParkedDIPJobsToParkedCat();
                    List<dbObjJobs> dbObjJobsListAL = DAO_Jobs.getAlldbObjJobsPerCategeoryWithOrigParkedJobs(6);

                    String lastpostal = objGlobalMethods.getGCMPrefs(gcmp, "lastpostal");
                    res = getAmendedJobQ(res, dbObjJobsListAL, lastpostal, gcmp, JobsPostalsToBeUNPARKED);
                    Gson gson = new Gson();
                    JobQueJsonStr = gson.toJson(res);
                    if (JobQueJsonStr != null && !JobQueJsonStr.equals("") && !JobQueJsonStr.equals("[]")) {
                        //objGlobalMethods.setGCMPrefs(gcmp, "NonProcessJobQueJsonStr", JobQueJsonStr);
                        objGlobalMethods.setVrpRelatedSP_KeyValue("NonProcessJobQueJsonStr", JobQueJsonStr);
                    } else {
                        //objGlobalMethods.setGCMPrefs(gcmp, "NonProcessJobQueJsonStr", "");
                        objGlobalMethods.setVrpRelatedSP_KeyValue("NonProcessJobQueJsonStr", "");
                    }
                } else if (res != null && res.length == 0) {
                    //objGlobalMethods.setGCMPrefs(gcmp, "NonProcessJobQueJsonStr", "");
                    objGlobalMethods.setVrpRelatedSP_KeyValue("NonProcessJobQueJsonStr", "");
                } else {
                    ////objGlobalMethods.setGCMPrefs(gcmp, "NonProcessJobQueJsonStr", "");
                }

                if (res != null && res.length > 0) {
                    for (int i = 0; i <= res.length - 1; i++) {
                        r = res[i];
                        hasOpsQue = r.getOPS_Queue() != null;
                        if (hasOpsQue) {
                            break;
                        }
                    }
                }

                if (hasOpsQue && IsMaintenanceHours)
                    hasOpsQue = false;

                objGlobalMethods.setGCMPrefs(gcmp, "hasOpsQue", hasOpsQue ? "t" : "");

                ////unpark jobs that has same postals as original pip dip jobs, must be after getJobQue2 due to VRP portion
                JobsHandler2.regroupParkedJobs("");
                ////unpark jobs that has same postals as original pip dip jobs, must be after getJobQue2 due to VRP portion

                Class<? extends Activity> c = null;
                if (myApp.currentActivity != null) {
                    c = myApp.currentActivity.getClass();
                }
                boolean IsDefaultVRPpage_ = objGlobalMethods.IsDefaultVRPpage() && !IsMaintenanceHours;
                final JobQueue[] ress = res;
                if (IsDefaultVRPpage_ && c != null && c == MapsAllActivity.class) {
                    final MapsAllActivity act = (MapsAllActivity) myApp.currentActivity;
                    act.runOnUiThread(new Runnable() {
                        public void run() {
                            // Notifiy activity
                            //objGlobalMethods.writeToFile("refreshing MapsAllActivity in getJobQue2.", "", "", "", "");
                            act.setUpMap2SQLiteByJobQue(null);
                        }
                    });
                } else if (!isEditingRoute && isRefresh && forceRefresh && c != null && c == DrawerMain2Activity.class) {
                    final DrawerMain2Activity act = (DrawerMain2Activity) myApp.currentActivity;
                    act.runOnUiThread(new Runnable() {
                        public void run() {
                            // Notifiy activity
                            //objGlobalMethods.writeToFile("refreshing VRP_Que Page in getJobQue2.", "", "", "", "");
                            if (ress != null && ress.length > 0) {
                                act.refreshrv(
                                        (
                                                (ListItemIndex != null && ListItemIndex.size() > 0) &&
                                                        (ListItemIndex.get(0) == -1 || ListItemIndex.get(0) == 0 || ListItemIndex.get(0) == 2 || ListItemIndex.get(0) == 6)
                                        )
                                );
                            } else {
                                act.extCallForRecalRoute();
                            }
                            //act.refreshrv();
                        }
                    });
                }
                /*else if (!isEditingRoute && c != null && c == DrawerMain2Activity.class && IsDefaultVRPpage_) {
                    final DrawerMain2Activity act = (DrawerMain2Activity) myApp.currentActivity;
                    act.runOnUiThread(new Runnable() {
                        public void run() {
                            if (ress != null && ress.length > 0) {
                                act.refreshrv();
                            } else {
                                act.extCallForRecalRoute();
                            }
                        }
                    });
                } */
                else if (hasOpsQue && c != null && c != DrawerMain2Activity.class && !IsDefaultVRPpage_) {
                    if (c == DrawerMainActivity.class || c == AddressListNewActivity.class || c == AddressListRoutingActivity.class || c == MapsAllActivity.class) {
                        if (c == DrawerMainActivity.class) {
                            String isrefreshing = objGlobalMethods.getGCMPrefs(gcmp, "isrefreshing");
                            if ((isrefreshing.isEmpty() || isrefreshing.equals("") || isrefreshing.equals("f"))) {
                                redirectToVrpPage();
                            }
                        } else {
                            redirectToVrpPage();
                        }
                    } else if (c == JobsListGroupActivity.class || c == DashboardSubActivity.class || c == JobInfoActivity.class || c == MapsActivity.class) {
                        boolean isReadingFirstQue_Location_Or_Job_ = isReadingFirstQue_Location_Or_Job(c);

                        if (!isReadingFirstQue_Location_Or_Job_) {
                            redirectToVrpPage();
                        }
                    }
                } else if (isRefresh && c == DrawerMainActivity.class) {
                    final DrawerMainActivity act = (DrawerMainActivity) myApp.currentActivity;
                    act.runOnUiThread(new Runnable() {
                        public void run() {
                            // Notifiy activity
                            if (ListItemIndex != null && ListItemIndex.size() > 0) {
                                for (int i = 0; i <= ListItemIndex.size() - 1; i++) {
                                    if (ListItemIndex.get(i) == 6) {
                                        act.updateListRowPerCategory(2, true);
                                        act.updateListRowPerCategory(ListItemIndex.get(i), true);
                                    } else {
                                        act.updateListRowPerCategory(ListItemIndex.get(i), true);
                                    }
                                }
                            }
                            /*if (ListItemIndex == 6) {
                                act.updateListRowPerCategory(2, true);
                            }

                            act.updateListRowPerCategory(ListItemIndex, true);*/
                        }
                    });
                }
            } else {
                objGlobalMethods.writeToFile("No network at JobsHandler getJobQue2.", "", "", "", "");
            }

        } catch (Exception e) {
            String s = getStackTraceString(e);
            objGlobalMethods.writeToFile("Exception at JobsHandler getJobQue2. Exception: " + e.getMessage().toString() + "\nStack: " + s, "", "", "", "");
        }
    }

    public static boolean isReadingFirstQue_Location_Or_Job(Class<? extends Activity> c) {
        boolean asd = false;
        ArrayList<JobQueue> NewJQlist = null;
        JobQueue j = null;
        String ProcessJobQueJsonStr = "";
        SharedPreferences gcmp = objGlobalMethods.getGcmPreferences();
        Gson gson = new Gson();
        String postal = "";
        Long JobsIDX = null;
        try {
            //ProcessJobQueJsonStr = objGlobalMethods.getGCMPrefs(gcmp, "ProcessJobQueJsonStr");
            ProcessJobQueJsonStr = objGlobalMethods.getVrpRelatedSP_KeyValue("ProcessJobQueJsonStr");
            if (!ProcessJobQueJsonStr.isEmpty() && !ProcessJobQueJsonStr.equals("") && !ProcessJobQueJsonStr.equals("[]")) {
                if (c == JobsListGroupActivity.class || c == MapsActivity.class || c == DashboardSubActivity.class) {
                    postal = objGlobalMethods.getGCMPrefs(gcmp, "desPostal");
                } else if (c == JobInfoActivity.class) {
                    objJobInfo currJobInfo = new Gson().fromJson(gcmp.getString("hfJobInfoJsonStr", ""), objJobInfo.class);
                    JobsIDX = currJobInfo.JobsIDX;
                }

                NewJQlist = gson.fromJson(ProcessJobQueJsonStr, new TypeToken<List<JobQueue>>() {
                }.getType());
                if (NewJQlist != null && NewJQlist.size() > 1) {
                    for (int i = 0; i <= NewJQlist.size() - 1; i++) {
                        j = NewJQlist.get(i);
                        if (j.IsHeader) {
                            continue;
                        } else if (j.getOPS_Queue() != null && (postal.isEmpty() || postal.equals("")) && JobsIDX != null && JobsIDX > 0 && j.JobsIDXsList != null && j.JobsIDXsList.size() > 0 && j.JobsIDXsList.contains(JobsIDX)) {
                            //check while reading JobInfoActivity
                            asd = true;
                            break;
                        } else if (j.getOPS_Queue() != null && !postal.isEmpty() && !postal.equals("") && j.PostalCode.equals(postal)) {
                            //check while reading JobsListGroupActivity or DashboardSubActivity or MapsActivity
                            asd = true;
                            break;
                        }
                    }
                } else {
                    asd = true;
                }
            } else {
                asd = true;
            }
        } catch (Exception e) {
            asd = false;
            objGlobalMethods.writeToFile("Exception at JobsHandler isReadingFirstQue_Location_Or_Job. Exception: " + e.getMessage(), "", "", "", "");
        } finally {
            return asd;
        }
    }

    public static void redirectToVrpPage2() {
        try {
            myApp.currentActivity.runOnUiThread(new Runnable() {
                public void run() {
                    AlertDialog.Builder builder = new AlertDialog.Builder(myApp.currentActivity);
                    builder.setTitle("");
                    builder.setCancelable(false);
                    builder.setMessage(myApp.getAppContext().getString(R.string.usevrp));

                    builder.setPositiveButton(myApp.getAppContext().getString(R.string.buttontext_ok), new DialogInterface.OnClickListener() {
                        @Override
                        public void onClick(DialogInterface dialog, int which) {
                            //if user pressed "yes", then he is allowed to exit from application
                            try {
                                if (myApp.currentActivity != null) {
                                    Class<? extends Activity> c = myApp.currentActivity.getClass();
                                    Intent p = new Intent(myApp.currentActivity, DrawerMain2Activity.class);
                                    objGlobalMethods.setGCMPrefs(objGlobalMethods.getGcmPreferences(), "pagemode", "vrp");
                                    objGlobalMethods.writeToFile("Auto switched to VRP Mode due isStdRunner && isSatSun && StdRunJobsCount == 0.", "", "", "", "");
                                    myApp.currentActivity.startActivity(p);
                                    actFinish();
                                }
                            } catch (ActivityNotFoundException e) {
                                String stack = JobsHandler.getStackTraceString(e);
                                objGlobalMethods.writeToFile("ActivityNotFoundException at JobsHandler redirectToVrpPage2 setPositiveButton onClick. ActivityNotFoundException: "
                                        + e.toString() + "\nStack: " + stack, "", "", "", "");
                            } catch (Exception e) {
                                objGlobalMethods.writeToFile("Exception at JobsHandler redirectToVrpPage2 setPositiveButton onClick. Exception: "
                                        + e.toString(), "", "", "", "");
                            }
                        }
                    });

                    AlertDialog alertdialog = builder.create();
                    alertdialog.show();
                }
            });
        } catch (Exception e) {
            objGlobalMethods.writeToFile("Exception at JobsHandler redirectToVrpPage2. Exception: " + e.getMessage(), "", "", "", "");
        }
    }

