    public static List<JobQueue> setCreditQues(List<JobQueue> njq, List<String> postals) {
        JobQueue j = null;
        try {
            if (postals == null || (postals != null && postals.size() == 0))
                return njq;

            for (int i = 0; i <= njq.size() - 1; i++) {
                j = njq.get(i);
                if (postals.contains(j.PostalCode)) {
                    njq.get(i).setIsEnabled(true);
                    njq.get(i).setisUpdated(true);
                }

            }
        } catch (Exception e) {
            String s = getStackTraceString(e);
            objGlobalMethods.writeToFile("Exception at JobsHandler setCreditQues. Exception: " + e.getMessage() + "\nStack: " + s, "", "", "", "");
        } finally {
            return njq;
        }
    }

