    public static List<JobQueue> enableValid(List<JobQueue> njq, Boolean istestuserID) {
        JobQueue j = null;
        boolean hasWeighted = false;
        try {
            for (int i = 1; i <= njq.size() - 1; i++) {
                j = njq.get(i);
                hasWeighted = ((j.Flag & 4) == 4) && !istestuserID;
                if (hasWeighted)
                    break;
            }
            if (hasWeighted) {
                for (int i = 1; i <= njq.size() - 1; i++) {
                    j = njq.get(i);
                    if (j.GC_Queue != null && j.GC_Queue > 0) {
                        njq.get(i).setIsEnabled(true);
                        njq.get(i).setisUpdated(true);
                    } else {
                        njq.get(i).setIsEnabled(((j.Flag & 4) == 4));
                        njq.get(i).setisUpdated(((j.Flag & 4) == 4));
                    }
                    /*njq.get(i).setIsEnabled(((j.Flag & 4) == 4));
                    njq.get(i).setisUpdated(((j.Flag & 4) == 4));*/
                }
            } else {
                for (int i = 1; i <= njq.size() - 1; i++) {
                    j = njq.get(i);
                    if ((istestuserID && j.Valid && j.GC_Queue != null) || j.HasStdRunJob) {
                        njq.get(i).setIsEnabled(true);
                        njq.get(i).setisUpdated(true);
                    } else if ((!istestuserID && j.Valid) || j.HasStdRunJob) {
                        njq.get(i).setIsEnabled(true);
                        njq.get(i).setisUpdated(true);
                    }

                    /*if ((j.Valid) || j.HasStdRunJob) {
                        njq.get(i).setIsEnabled(true);
                        njq.get(i).setisUpdated(true);
                    }*/
                }
            }

        } catch (Exception e) {
            String s = getStackTraceString(e);
            objGlobalMethods.writeToFile("Exception at JobsHandler enableValid. Exception: " + e.getMessage() + "\nStack: " + s, "", "", "", "");
        } finally {
            return njq;
        }
    }

    public static List<JobQueue> vicinityChk(List<JobQueue> njq, Location lastknownlocation) {
        float radius = 0;
        float dist = 0;
        JobQueue j = null;
        JobQueue j2 = null;
        Location a = new Location("a");
        Location b = new Location("b");
        int idx = 1;
        boolean uselastknownloc = false;
        try {
            if (njq.size() > 2) {
                j = njq.get(1);
                j2 = njq.get(2);
                a.setLatitude(j.Latitude);
                a.setLongitude(j.Longitude);
                b.setLatitude(j2.Latitude);
                b.setLongitude(j2.Longitude);
            } else if (njq.size() == 2) {
                a = lastknownlocation;
                j2 = njq.get(1);
                b.setLatitude(j2.Latitude);
                b.setLongitude(j2.Longitude);
                uselastknownloc = true;
            }

            radius = JobsHandler2.getDistance(a, b, 1.1f);

            while (radius <= 10 && idx <= njq.size() - 1) {
                idx++;
                if (!uselastknownloc) {
                    j = njq.get(idx);
                    a.setLatitude(j.Latitude);
                    a.setLongitude(j.Longitude);
                } else {
                    a = lastknownlocation;
                }
                j2 = njq.get(idx + 1);
                b.setLatitude(j2.Latitude);
                b.setLongitude(j2.Longitude);
                radius = JobsHandler2.getDistance(a, b, 1.1f);
            }

            for (int i = 2; i <= njq.size() - 1; i++) {
                j2 = njq.get(i);
                b.setLatitude(j2.Latitude);
                b.setLongitude(j2.Longitude);
                dist = JobsHandler2.getDistance(a, b, 1);
                if (dist <= radius) {
                    njq.get(i).setOptional(true);
                    njq.get(i).setIsEnabled(true);
                    njq.get(i).setisUpdated(true);
                }
            }

        } catch (Exception e) {
            String s = getStackTraceString(e);
            objGlobalMethods.writeToFile("Exception at JobsHandler vicinityChk. Exception: " + e.getMessage() + "\nStack: " + s, "", "", "", "");
        } finally {
            a = null;
            b = null;
            return njq;
        }
    }

